            { type = "list_item", text = "Templar: Hammer of Light’s damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "dev_note", text = "Mindgames has fallen behind other spells and has been an underutilized talent for some time, so we’re increasing its viability to offer all Priest specializations more PvP talent options.", level = 1 },
            { type = "list_item", text = "Mindgames direct damage increased by 150%.", level = 1 },
            { type = "list_item", text = "Mindgames healing and damage reversal increased by 150%.", level = 1 },
            { type = "list_item", text = "Discipline", level = 1 },
            { type = "list_item", text = "Flash Heal and Shadow Mend healing increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Atonement healing increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "dev_note", text = "Holy Priest is vastly overperforming due to a mixture of overall healing increases from the patch as well as some generous PvP specific healing increases to Prayer of Mending and Holy Word: Serenity. We’re reducing these PvP increases to Prayer of Mending, Holy Word: Serenity, and Prompt Prognosis which are all powerful instant cast spells.", level = 2 },
            { type = "list_item", text = "Enlightenment regenerates mana 10% faster in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Prayer of Mending healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy Word: Serenity healing reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Oracle: Prompt Prognosis healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow", level = 1 },
            { type = "dev_note", text = "We feel Shadow is lacking in kill power, so we’re increasing some of its primary sources of burst.", level = 2 },
            { type = "list_item", text = "Shadow Word: Madness damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Void Volley damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow Word: Death damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rogue", level = 0 },
            { type = "list_item", text = "Assassination", level = 1 },
            { type = "dev_note", text = "Burst from Assassination’s Apex Talent is exceeding expectations and is getting toned down. Additionally, damage from Fatebound Coins is higher than intended and is being reduced.", level = 2 },
            { type = "list_item", text = "Kingsbane initial damage reduced by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Implacable (Rank 3) Physical and Nature damage reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fatebound: Fatebound Coin (Tails) damage reduced by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Outlaw", level = 1 },
            { type = "dev_note", text = "Outlaw’s damage and kill pressure is lower than we’d expect, so we’re putting more damage into core finishing moves.", level = 2 },
            { type = "list_item", text = "Dispatch damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Between the Eyes damage increased by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Subtlety", level = 1 },
            { type = "dev_note", text = "Subtlety’s steady damage pressure is low, without which it can be difficult to create windows that capitalize on their burst potential. We’re increasing Eviscerate damage moderately and Goremaw’s Bite bleed damage significantly to increase the frequency of these windows.", level = 2 },
            { type = "list_item", text = "Eviscerate damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Goremaw’s Bite bleeding damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Elemental", level = 1 },
            { type = "dev_note", text = "Elemental is lacking the sustained pressure we expect, so we’re targeting core damage sources to improve its viability.", level = 2 },
            { type = "list_item", text = "Stormbringer: Tempest damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Lava Burst damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earth Shock damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earthquake damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "Restoration Shaman is slightly too strong compared to other healers (barring Holy Priest). We’re making some small adjustments to their mana and the Totemic hero talent tree to better balance their mana and throughput.", level = 2 },
            { type = "list_item", text = "Mana regeneration is now reduced by 65% in PvP combat (was 60%).", level = 2 },
            { type = "list_item", text = "Totemic: Splitstream now causes Healing Stream Totem to heal an additional ally at 15% effectiveness in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Totemic: Earthsurge now causes allies affected by your Earthliving to receive 5% additional healing from you in PvP combat (was 15%).", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "dev_note", text = "We’re increasing Affliction’s ability to maintain spread pressure by adjusting Agony’s damage and making a small adjustment to Unstable Affliction’s backlash damage to make dispelling all their damage over time effects more punishing.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Unstable Affliction backlash damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "dev_note", text = "We feel too much of Demonology’s damage is focused on Wicked Reaping and Power Siphon, so we’re reducing the power of these effects and increasing overall damage through our game-wide Demonology changes above.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Wicked Reaping damage reduced by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Necrolyte Teachings now causes Power Siphon to increase the damage of Demonbolt by an additional 10% in PvP combat (was 20%).", level = 2 },
            { type = "list_item", text = "Power Siphon now increases the damage of your next 2 Demonbolts by 20% in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "dev_note", text = "Destruction is lacking in finishing power, so we’re increasing the damage of their primary nuke spells to allow for more burst potential.", level = 2 },
            { type = "list_item", text = "Chaos Bolt damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadowburn damage increased by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Arms", level = 1 },
            { type = "dev_note", text = "To compensate for the reduction in Fueled by Violence self-healing, we’re increasing Arms’ Hero Talents throughput by increasing Slayer’s Strike and Demolish damage in PvP.", level = 2 },
            { type = "list_item", text = "Colossus: Demolish damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Slayer: Slayer’s Strike damage increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fueled by Violence healing reduced by 15% in PvP combat.", level = 2 },
