            title = "Bloom Bright with the Vibrant Petalweave Collection",
            category = "Blogs (EU)",
            timestamp = 1787682647,
            url = "https://news.blizzard.com/en-gb/article/24298582/bloom-bright-with-the-vibrant-petalweave-collection",
            content = {
            { type = "p", text = "Fresh-picked fashion is ready to take root across Azeroth. From sunlit strolls to magical midsummer nights, the Vibrant Petalweave Collection* blooms with style." },
            { type = "p", text = "Get the complete collection in one bundle, or pick your favorite floral hues individually:" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-25-bloom-bright-with-the-vibrant-petalweave-collection-a9915f258e\\image-1.jpg" },
            { type = "p", text = "Sunlit Petalweave Ensemble (Transmog Set)" },
