            { type = "p", text = "Blush Petalweave Ensemble (Transmog Set)" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-25-bloom-bright-with-the-vibrant-petalweave-collection-a9915f258e\\image-3.jpg" },
            { type = "p", text = "Azure Petalweave Ensemble (Transmog Set)" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-25-bloom-bright-with-the-vibrant-petalweave-collection-a9915f258e\\image-4.jpg" },
            { type = "p", text = "Scarlet Petalweave Ensemble (Transmog Set)" },
            { type = "p", text = "If you already have one or more items from the bundle in your in-game Collection, the price will automatically adjust so you only pay for the items you haven’t collected." },
            { type = "p", text = "Each Petalweave Ensemble includes the following transmog pieces:" },
            { type = "list_item", text = "Petalweave Crown", level = 0 },
            { type = "list_item", text = "Petalweave Mantle", level = 0 },
            { type = "list_item", text = "Petalweave Halter", level = 0 },
            { type = "list_item", text = "Petalweave Belt", level = 0 },
            { type = "list_item", text = "Petalweave Skirt", level = 0 },
            { type = "list_item", text = "Petalweave Boots", level = 0 },
            { type = "list_item", text = "Petalweave Gloves", level = 0 },
            { type = "list_item", text = "Petalweave Cloak", level = 0 },
            { type = "p", text = "Shop the Collection" },
            { type = "hr" },
            { type = "p", text = "Bring a little bloom to your adventures—pluck the Vibrant Petalweave Collection out of the in-game Shop or at Battle.net. For the full details, visit shop.battle.net." },
            { type = "p", text = "*Requires a World of Warcraft® subscription or Game Time and is not available in World of Warcraft Classic® games." },
            },
        },
