        ["2026-08-25-set-out-with-the-hearthkeepers-wandering-caravan-mount-1a68897895"] = {
            id = "2026-08-25-set-out-with-the-hearthkeepers-wandering-caravan-mount-1a68897895",
            post_key = "1a68897895",
            title = "Set Out with the Hearthkeeper’s Wandering Caravan Mount",
            category = "Blogs (EU)",
            timestamp = 1787682634,
            url = "https://news.blizzard.com/en-gb/article/24298583/set-out-with-the-hearthkeepers-wandering-caravan-mount",
            content = {
            { type = "p", text = "Bring a little extra comfort on every journey with the Hearthkeeper’s Wandering Caravan* ground mount—it’s the coziest way to hoof it." },
            { type = "p", text = "Whether you’re pushing deeper into dangerous territory, tending to your bags between adventures, or checking your mail far from town, the Hearthkeeper’s Wandering Caravan keeps repair, mailbox access, and a higher perch close at hand. You’ll be ready to go the distance, with no ox-cuse to cut your expeditions short." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-25-set-out-with-the-hearthkeepers-wandering-caravan-mount-1a68897895\\image-1.jpg" },
            { type = "p", text = "Once added to your collection, the Hearthkeeper’s Wandering Caravan will be available to all current and future World of Warcraft Modern characters on your Battle.net account, traveling as fast as each character’s highest riding skill allows." },
            { type = "p", text = "Claim Your Caravan" },
            { type = "p", text = "Ready to make camp wherever adventure calls? Add the Hearthkeeper’s Wandering Caravan ground mount to your collection through the in-game Shop or at Battle.net. For full details, visit shop.battle.net." },
            { type = "hr" },
            { type = "p", text = "*Requires a World of Warcraft® subscription or Game Time and is not available in World of Warcraft Classic® games." },
            },
        },
        ["2026-08-25-set-out-with-the-hearthkeepers-wandering-caravan-mount-6f6389b585"] = {
