            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-25-set-out-with-the-hearthkeepers-wandering-caravan-mount-6f6389b585\\image-1.jpg" },
            { type = "p", text = "Once added to your collection, the Hearthkeeper’s Wandering Caravan will be available to all current and future World of Warcraft Modern characters on your Battle.net account, traveling as fast as each character’s highest riding skill allows." },
            { type = "p", text = "Claim Your Caravan" },
            { type = "p", text = "Ready to make camp wherever adventure calls? Add the Hearthkeeper’s Wandering Caravan ground mount to your collection through the in-game Shop or at Battle.net. For full details, visit shop.battle.net." },
            { type = "hr" },
            { type = "p", text = "*Requires a World of Warcraft® subscription or Game Time and is not available in World of Warcraft Classic® games." },
            },
        },
        ["2026-08-25-hotfixes-august-25-2026-15987718cd"] = {
            id = "2026-08-25-hotfixes-august-25-2026-15987718cd",
            post_key = "15987718cd",
            title = "Hotfixes: August 25, 2026",
            category = "Blogs (EU)",
            timestamp = 1787678131,
            url = "https://news.blizzard.com/en-gb/article/24296142/hotfixes-august-25-2026",
            content = {
            { type = "p", text = "Here you'll find a list of hotfixes that address various issues related to World of Warcraft: Midnight, Mists of Pandaria Classic, Season of Discovery, Burning Crusade Classic, WoW Classic Era, and Hardcore. Some of the hotfixes below take effect the moment they were implemented, while others may require scheduled realm restarts to go into effect. Please keep in mind that some issues cannot be addressed without a client-side patch update. This list will be updated as additional hotfixes are applied." },
            { type = "h2", text = "HOTFIXES" },
            { type = "hr" },
            { type = "h3", text = "August 25, 2026" },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Death Knight", level = 0 },
            { type = "dev_note", text = "Frost Death Knight has performed under our expectations at the beginning of Curse of Ula'tek, especially in the Venomous Abyss raid.", level = 1 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "list_item", text = "All ability damage and melee damage increased by 6%.", level = 2 },
            { type = "list_item", text = "Obliterate damage increased by 15%.", level = 2 },
            { type = "list_item", text = "Unholy", level = 1 },
            { type = "list_item", text = "Resolved an issue causing the Unholy Devotion attack speed increase to also reduce attack damage and therefore have a neutral effect.", level = 2 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Vengeance", level = 1 },
            { type = "list_item", text = "Mastery: Fel Blood effectiveness increased by 24%.", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "These changes are intended to address Rejuvenation and Wild Growth feeling weak in season 2, particularly in dungeons. We’re also increasing the power of the 4-piece class set to make sure it's an impactful and noticeable set bonus. These changes are accompanied by slight nerfs to their raid healing to keep them around the same power in raid while increasing their power in dungeons.", level = 2 },
            { type = "list_item", text = "4-piece class set bonus increases Genesis duration by 8 seconds (was 4 seconds).", level = 2 },
            { type = "list_item", text = "Rejuvenation and Germination healing increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wild Growth healing increased by 10%.", level = 2 },
            { type = "list_item", text = "Nature's Bounty replicates 10% of Regrowth's healing (was 20%).", level = 2 },
            { type = "list_item", text = "Everbloom heals 5 targets (was 6 targets).", level = 2 },
            { type = "list_item", text = "Everbloom heals for 48% of Lifebloom's final heal (was 40%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Preservation", level = 1 },
            { type = "dev_note", text = "We’re further increasing some of the Preservation triage heals to help them keep up with other healers in dungeons.", level = 2 },
            { type = "list_item", text = "Verdant Embrace healing increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Living Flame healing increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Dream Simulacrum increases healing of Verdant Embrace by 40% (was 30%).", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Beast Mastery", level = 1 },
            { type = "dev_note", text = "We’re looking to increase Beast Mastery area damage and cleave capabilities.", level = 2 },
            { type = "list_item", text = "Wild Thrash now deals 300% increased damage when striking more than 2 targets (was 200%).", level = 2 },
            { type = "list_item", text = "Beast Cleave now causes your pets to strike nearby enemies for 70% of the damage dealt (was 55%).", level = 2 },
            { type = "list_item", text = "Survival", level = 1 },
            { type = "list_item", text = "All damage dealt by you and your pets increased by 4%.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "dev_note", text = "We're primarily focused on Frost's performance in Mythic Keystone dungeons. The recent removal of the health increase from Improved Ice Barrier had a greater effect on Frost's overall survivability than intended. We like the symmetry of the three Improved Barrier talents having one additional effect, and Frost has historically had a slightly larger absorb than Arcane and Fire, so we're baking it into the baseline absorb amount rather than re-attaching it to Improved Ice Barrier. We're also making some targeted increases to Frost's area of effect damage.", level = 2 },
            { type = "list_item", text = "Ice Barrier absorb amount increased to 35% of maximum health (was 30%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Blizzard damage increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostbite Talent: Shatter damage to nearby enemies increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostfire: Isothermic Core - Meteor damage increased by 25%.", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Brewmaster", level = 1 },
            { type = "list_item", text = "Developers’ note: We’re adjusting the absorption of Celestial Brew and Celestial Infusion to improve its impact as a defensive option and to help address pain points players are experiencing in some encounters.", level = 2 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Celestial Brew and Celestial Infusion absorb value increased by 20%.", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "We're increasing the damage of the Curse of Ula'tek 4-piece set bonus Divine Arbiter significantly, to make sure its rotational ask is worth executing.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter main target damage increased by 150%.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter secondary target damage increased by 75%.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "dev_note", text = "We’re increasing the throughput of Affliction and Demonology by primarily focusing on their single-target tools with a secondary focus on their multi-target kit. Additionally, we’re considerably increasing the damage of Warlock demons so that they have a larger contribution to overall throughput. This should also help a bit more with aggro concerns during solo play.", level = 1 },
            { type = "list_item", text = "Imp, Voidwalker, Sayaad, and Felhunter damage increased by 350%.", level = 1 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Unstable Affliction damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Blackened Soul damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wrath of Nathreza damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow of Nathreza damage increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Corruption damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Wither damage increased by 10%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "list_item", text = "Shadow Bolt damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonbolt damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Wild Imp damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Summon Felguard damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demons summoned by Dominion of Argus damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Call Dreadstalkers damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Rain of Fire damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Fight Through the Flames reduces Magic damage by 8% (was 6%).", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "Fixed an issue where Valeera could no longer gain experience from mislaid curiosities.", level = 0 },
            { type = "h3", text = "Dungeons and Raids" },
            { type = "list_item", text = "The Tidebound Grotto", level = 0 },
            { type = "list_item", text = "Health of Nymrissa Wavecaller reduced by 5% on Heroic difficulty and 10% on Mythic difficulty.", level = 1 },
            { type = "list_item", text = "Abyssal Rain's initial damage reduced by 12.5%.", level = 1 },
            { type = "list_item", text = "Abyssal Rain's periodic damage reduced by 12% on Heroic difficulty and 20% on Mythic difficulty.", level = 1 },
            { type = "list_item", text = "Reduced Abyssal Rain’s damage scaling for larger groups.", level = 1 },
            { type = "list_item", text = "Frost Burst damage reduced by 40%.", level = 1 },
