            { type = "list_item", text = "Toadspawn target radius reduced to 3-7 yards (was 10 yards), and eggs now finish hatching even if the Matriarch is dead.", level = 2 },
            { type = "list_item", text = "Ikuzz the Light Hunter", level = 1 },
