            { type = "list_item", text = "Murder Row", level = 0 },
            { type = "list_item", text = "Addressed an issue where Malefic Wave can sometimes fail to hit players.", level = 1 },
            { type = "list_item", text = "Addressed an issue where Row Snitch can be uninteractable.", level = 1 },
            { type = "list_item", text = "Lithiel Cinderfury", level = 1 },
            { type = "list_item", text = "Fingers of Gul’dan now prefers non-tank players.", level = 2 },
            { type = "list_item", text = "Fingers of Gul’Dan number of targets reduced to 4 (was 5).", level = 2 },
            { type = "list_item", text = "Fingers of Gul’dan number of Wild Imps summoned increased to 4 (was 3).", level = 2 },
            { type = "list_item", text = "Ruby Life Pools", level = 0 },
            { type = "list_item", text = "Replaced the Flashfrost Chillweaver nearest to Defier Draghar with a Deepstone Earthshaper, and moved one of the preceding Earthbound Guardians next to this creature.", level = 1 },
            { type = "list_item", text = "Adjusted enemy forces requirement to keep routing the same as before.", level = 2 },
            { type = "list_item", text = "Deepstone Earthshaper’s health reduced by 8%, and Techtonic Strikes damage vulnerability reduced to 25% (was 35%).", level = 1 },
            { type = "list_item", text = "Flashfrost Chillweaver’s health reduced by 10%.", level = 1 },
            { type = "list_item", text = "Primalist Cinderweaver’s Living Bomb periodic damage and explosion damage reduced by 10%.", level = 1 },
            { type = "list_item", text = "Temple of Sethraliss", level = 0 },
            { type = "list_item", text = "Replaced a Faithless Subjugator with a Lightning Serpent.", level = 1 },
            { type = "list_item", text = "Adjusted enemy forces requirement to keep routing the same as before.", level = 2 },
            { type = "list_item", text = "Swarming Krolusks now idle for longer after spawning before attacking.", level = 1 },
            { type = "list_item", text = "Voidscar Arena", level = 0 },
            { type = "list_item", text = "Adjusted spawning of a pack near the Harrower to be closer to the stairs.", level = 1 },
            { type = "list_item", text = "Taz'Rah", level = 1 },
            { type = "list_item", text = "Nether Dash line visuals now turn more smoothly.", level = 2 },
            { type = "list_item", text = "Atroxus", level = 1 },
            { type = "list_item", text = "Addressed issues with the voice lines not matching the spells.", level = 2 },
            { type = "list_item", text = "The Venomous Abyss", level = 0 },
            { type = "list_item", text = "Reduced the number of creature spawns throughout the zone.", level = 1 },
            { type = "list_item", text = "Reduced the blood required to open doors throughout the Venomous Abyss.", level = 1 },
            { type = "list_item", text = "Reduced the damage of Venom Withdrawal by 30%.", level = 1 },
            { type = "list_item", text = "Reduced the duration of Venom Withdrawal by 50%.", level = 1 },
            { type = "list_item", text = "Reduced the health of Serpent Wards by 75%.", level = 1 },
            { type = "list_item", text = "The Lost Explorers", level = 1 },
            { type = "list_item", text = "Resolved an issue where Hoji did not immediately stop casting when the encounter ends, preventing the encounter from completing.", level = 2 },
            { type = "list_item", text = "Vashnik the Malignant", level = 1 },
            { type = "list_item", text = "Fixed an issue causing the Solidified Snake Venom to not spawn for the achievement.", level = 2 },
            { type = "list_item", text = "Fixed an issue causing Burning Venom to not move towards the Malignant Cavity after being gripped.", level = 2 },
            { type = "list_item", text = "Reduced the number of Malignant Totems per cast.", level = 2 },
            { type = "list_item", text = "Adjusted the spawn locations of Malignant Totems.", level = 2 },
            { type = "list_item", text = "Fixed a bug causing Imbibe to inflict more damage than intended on Normal and Heroic difficulties.", level = 2 },
            { type = "list_item", text = "The Coiled Altar", level = 1 },
            { type = "list_item", text = "Fixed an issue where Sever's vulnerability aura lasted longer than intended.", level = 2 },
            { type = "list_item", text = "Malacrass now casts Dreadmarch on all players 10 seconds after he enrages.", level = 2 },
            { type = "list_item", text = "Reduced Malacrass’s phase 3 health by 10% on Normal and Heroic difficulties.", level = 2 },
            { type = "list_item", text = "Eternal Nightfall is no longer affected by Curse of Tongues or similar effects.", level = 2 },
            { type = "list_item", text = "Reduced the absorb value of Veil of Twilight by 15% on Normal and Heroic difficulties.", level = 2 },
            { type = "list_item", text = "Ula’tek", level = 1 },
            { type = "list_item", text = "Corrected the target location of Ula'tek's Venomous Heart so that AoE spells more consistently hit it and Ula'tek.", level = 2 },
            { type = "list_item", text = "Fixed a bug preventing the encounter from resetting when no players were alive in Ula’tek’s room.", level = 2 },
            { type = "list_item", text = "Increased the duration of Greasy Hatchling to 35 seconds (was 20 seconds).", level = 2 },
            { type = "list_item", text = "Players are now protected against being targeted by Virulent Spit while crossing the venom pools.", level = 2 },
            { type = "list_item", text = "Resolved an issue causing Death Knights’ Necrotic Coil to have pathing issues.", level = 2 },
            { type = "list_item", text = "Causing the Doomscale Warden to cast Shadow Molt early no longer resets their spell record timings.", level = 2 },
            { type = "list_item", text = "Reduced the number of players required to successfully soak Serpent's Bite across the range of raid sizes.", level = 2 },
            { type = "list_item", text = "Players affected by Calcified Corpse now radiate massive raid damage on Heroic and Mythic difficulties.", level = 2 },
            { type = "list_item", text = "An erroneous tenth stack of Stone Venom is no longer applied to the current target during Ula'tek's Mother's Wrath.", level = 2 },
            { type = "h3", text = "Housing" },
            { type = "list_item", text = "Previewing decor in the Decor Catalog will now show accurate Voidlight Marl prices for decor sold by Silvermoon's Disguised Decor Duel Vendor.", level = 0 },
            { type = "h3", text = "Omnium Folio" },
            { type = "list_item", text = "Fixed a bug that where the Rune of Lingering did not always activate for healers.", level = 0 },
            { type = "h3", text = "Player versus Player" },
            { type = "list_item", text = "In Training Grounds, Arena opponents will now properly display their surrender animation when forfeiting their match after a teammate has died.", level = 0 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "dev_note", text = "We feel the defensive kits of Devourer and Havoc are too powerful, so we are reducing some of their passive and active defenses to make them more viable targets for opponents.", level = 1 },
            { type = "list_item", text = "Glimpse now reduces damage taken by 20% while active (was 25%).", level = 1 },
            { type = "list_item", text = "Devourer", level = 1 },
            { type = "list_item", text = "Void Ray damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Armor of Souls now increases Armor by 65% (was 100%).", level = 2 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Desperate Instincts now reduces damage taken by 5% while below 35% health in PvP combat (was 10%).", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Feral", level = 1 },
            { type = "dev_note", text = "Feral’s sustained damage is lower than our intended target, so we’re targeting their primary damage over time effects to improve this. We’re also targeting a buff for Druid of the Claw which has fallen behind Wildstalker in viability.", level = 2 },
            { type = "list_item", text = "Druid of the Claw: Ravage damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rip damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rake damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Augmentation", level = 1 },
            { type = "dev_note", text = "Augmentation has been underplayed in PvP, especially arenas, for some time. We're increasing both their damage support capabilities and their personal damage to increase their viability.", level = 2 },
            { type = "list_item", text = "Damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Ebon Might grants 10% primary stat in PvP combat (was 8%).", level = 2 },
            { type = "list_item", text = "Inferno's Blessing damage increased by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "dev_note", text = "Sentinel Hunters are slightly too strong during burst windows in PvP, so we're reducing the damage of Moonlight Chakram and increasing the throughput of rotational abilities to compensate.", level = 1 },
            { type = "list_item", text = "Marksmanship", level = 1 },
            { type = "list_item", text = "Sentinel: Moonlight Chakram damage reduced by 30% in PvP combat.", level = 2 },
