            { type = "list_item", text = "The weekly quest \"Midnight: Vaults of Atal'Utek\" no longer incorrectly suggests that it rewards two Sparks of Tide. This was a UI typo only.", level = 0 },
            { type = "list_item", text = "Fixed an issue that would prevent \"Purging the Vaults\" or \"Vaults of Atal'Utek: A Toxic Tour\" quests from being completed if you already had Trovehunter's Bounty in your inventory.", level = 0 },
            { type = "list_item", text = "The required Quest Item for “Seeking Knowledge Week 5 of 5: Off-World Magic” can now drop from Elite Rares, Overseers, and Rivals on Val and Naigtal.", level = 0 },
            { type = "hr" },
            { type = "h3", text = "August 18, 2026" },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Death Knight", level = 0 },
            { type = "list_item", text = "Blood", level = 1 },
            { type = "list_item", text = "Deathbringer: Resolved an issue causing Echoing Fury to grnt Exterminate stacks on Reaper’s Mark casts.", level = 2 },
            { type = "list_item", text = "San’layn: Visceral Strength now grants 6% strength (was 10%).", level = 2 },
            { type = "list_item", text = "San’layn: Transfusion increases Dancing Rune Weapon damage by 5% (was 10%).", level = 2 },
            { type = "dev_note", text = "The tooltip will be updated at a later date to reflect the new value.", level = 3 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "list_item", text = "All ability and auto-attack damage increased by 9%.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 2-piece set bonus updated – Now grants 1% attack speed per stack (was 2%), and now increases Icy Death Torrent damage by 2% per stack (was 4%).", level = 2 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Devourer", level = 1 },
            { type = "dev_note", text = "Devourer’s 4-piece set bonus is performing significantly above expectations, so we’re reducing its power. To compensate for this set bonus reduction, we’re increasing all ability damage. Additionally, Devourer has been overperforming, mostly in single target, so we are reducing the damage of Reap/Cull/Eradicate while increasing the AoE damage portion of Eradicate to reduce the impact of the change in AoE combat.", level = 2 },
            { type = "list_item", text = "All ability damage increased by 14%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Reap/Cull/Eradicate damage reduced by 12%.", level = 2 },
            { type = "list_item", text = "Eradicate’s area-of-effect damage increased to 90% of base damage (was 85%).", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Now generates 2 soul fragments (was 8 soul fragments) and increases Reap damage by 10% (was 20%).", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "We’re increasing Restoration Druid’s healing and damage as both aspects are underperforming relative to other healers.", level = 2 },
            { type = "list_item", text = "All healing increased by 4%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "All damage increased by 20%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Reduced the size of several Hydra creatures after they have been tamed.", level = 1 },
            { type = "list_item", text = "Beast Mastery", level = 1 },
            { type = "dev_note", text = "The new Venomous Abyss tier set bonus isn’t quite as strong as we would like it to be, so we’re increasing the effects of the 4-piece set bonus.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Now causes Cobra Shot to benefit from Beast Cleave at 30% effectiveness per stack (was 20%) or strike your target for an additional 20% damage per stack (was 15%).", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Arcane", level = 1 },
            { type = "dev_note", text = "The Venomous Abyss set bonus is overperforming our target tuning for set bonuses. However, the amount we need to reduce its value by would be a greater impact than intended to Arcane’s overall damage, so we are also making a small positive adjustment to Arcane’s baseline.", level = 2 },
            { type = "list_item", text = "All ability damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 2-piece set bonus updated – Arcane Missiles damage bonus reduced to 5% (was 20%).", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Cumulative Power damage bonus per stack reduced to 3% (was 5%).", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Mistweaver", level = 1 },
            { type = "dev_note", text = "Mistweaver has been underperforming so we are targeting increases to its casted healing and the Venomous Abyss 4-set bonus to improve its performance and maintain build diversity.", level = 2 },
            { type = "list_item", text = "All healing increased by 8%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Activation rate increased by 33%.", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "list_item", text = "All ability damage increased by 6%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "list_item", text = "Discipline", level = 1 },
            { type = "dev_note", text = "We’re reducing Discipline’s damage done and offsetting this in Atonement to not affect their overall healing, as their damage has been overperforming compared to other healers. At the same time, we’re increasing the damage of Entropic Rift to minimize the impact this will have on Voidweaver’s dungeon viability and help maintain high damage as one of its strengths.", level = 2 },
            { type = "list_item", text = "All damage reduced by 30%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Oracle: Entropic Rift damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Oracle: Atonement now transfers 46% of damage into healing (was 32%). Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Oracle: Void Shield reflects 10% of damage (was 15%).", level = 2 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "dev_note", text = "We’re increasing the healing throughput of Oracle so that it can serve as a competitive option against Archon. Furthermore, we are increasing the mana regeneration of Enlightenment to further help Holy Priest’s mana economy.", level = 2 },
            { type = "list_item", text = "Enlightenment now regenerates mana 25% faster (was 10%).", level = 2 },
            { type = "list_item", text = "Words of the Wise now increases the healing of Holy Word: Serenity and Holy Word: Sanctify by 40% (was 10%). Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Prompt Prognosis healing increased by 55%. Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Preventive Measures now increases Prayer of Mending healing by 40% (was 15%). Does not affect PvP combat.", level = 2 },
            { type = "list_item", text = "Rogue", level = 0 },
            { type = "list_item", text = "Assassination", level = 1 },
            { type = "list_item", text = "All damage increased by 4%.", level = 2 },
            { type = "list_item", text = "Subtlety", level = 1 },
            { type = "dev_note", text = "Subtlety’s 4-piece set bonus is overperforming expectations, so its effectiveness is being reduced. An overall buff to Subtlety’s damage is being applied to compensate.", level = 2 },
            { type = "list_item", text = "All damage increased by 6%.", level = 2 },
            { type = "list_item", text = "The Venomous Abyss 4-set bonus has been updated – Effectiveness reduced to 60% (was 100%).", level = 2 },
            { type = "list_item", text = "Shadow Dance now cancels when swapping talents.", level = 2 },
            { type = "list_item", text = "Shadow Dance can no longer be cancelled manually.", level = 2 },
            { type = "list_item", text = "Deathstalker: Lingering Darkness now cancels when swapping talents.", level = 2 },
            { type = "list_item", text = "Deathstalker: Lingering Darkness now cancels when a raid encounter starts.", level = 2 },
            { type = "list_item", text = "Deathstalker: Lingering Darkness now cancels when an M+ dungeon starts.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Elemental", level = 1 },
            { type = "list_item", text = "Corrected an issue where the Venomous Abyss 4-piece set bonus Overcharge! buff was sometimes not consumed when casting a Maelstrom spending ability.", level = 2 },
            { type = "list_item", text = "All damage dealt increased by 5%.", level = 2 },
            { type = "dev_note", text = "We discovered and fixed a tricky bug that was active on the PTR, that was increasing the amount of free Maelstrom spending abilities Elemental Shaman could get from the Venomous Abyss 4-piece set bonus. This was inflating their damage dealt, so alongside the bug fix, we're increasing their damage to compensate.", level = 3 },
            { type = "list_item", text = "Enhancement", level = 1 },
            { type = "list_item", text = "All damage increased by 5%.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Hellcaller: Fixed an issue where Blackened Soul would not function with mouse-over casting.", level = 1 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Fixed an issue where Withering Bolt would not account for Wither.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "list_item", text = "Burning Cleave (granted by Antoran Armaments) now strikes enemies in a circular area, rather than a cone. The tooltip for Burning Cleave will be updated in a future patch.", level = 2 },
            { type = "dev_note", text = "We are increasing the throughput of the Venomous Abyss 2-set bonus for Demonology so that its performance is closer to other specialization tier set bonuses.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 2-piece set bonus updated – Wild Imps now Implode at 350% effectiveness to their main target (was 250%) and 315% effectiveness to other targets (was 225%).", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Fixed an issue where Conflagration of Chaos would not guarantee a Conflagrate or Shadowburn to critically strike.", level = 2 },
            { type = "list_item", text = "Fixed an issue where Shadowburn would not apply its debuff after dealing damage to a Havoc target.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "dev_note", text = "Fury’s 4-piece set bonus is currently overperforming, but Fury is in a good place overall and we don’t want to disrupt that, so we’re moving some of the value out of the 4-piece bonus and into Fury’s baseline. Additionally, Slayer has been overperforming for both specs due to a bug causing Executioner to provide double value which was recently hotfixed. This fix has brought overall Arms performance down into our intended range, but we’re happy with where Fury has been, so their baseline damage has been increased below to compensate for this fix as well as the set bonus change.", level = 1 },
            { type = "list_item", text = "Fury", level = 1 },
            { type = "list_item", text = "All damage increased by 6%.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Bloodthirst damage increased by 10%, and during Recklessness, Bloodthirst increases the critical strike bonus of Recklessness by 3%, up to 6% (was 5%, up to 10%).", level = 2 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Mountain Thane: Fixed an issue that would sometimes disable the bonus Thunder Clap damage from Crashing Thunder.", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "The initial Ancient Golem in the Game Night variant of the Ring of Glory delve no longer attacks before being activated.", level = 0 },
            { type = "list_item", text = "“Delve into the Earth” should no longer be blocked if selecting a combat roll for Brann failed to advance the quest while outside a delve.", level = 0 },
            { type = "list_item", text = "Fixed an issue where Dundun's Favor would prevent Mislaid Curiosities from being looted by more than one party member.", level = 0 },
