            { type = "list_item", text = "Chilling Frost duration reduced by 1.5 seconds.", level = 1 },
            { type = "list_item", text = "Reduced the number Bubblefin Frostscales that appear with each wave of murlocs to 2 (was 3).", level = 1 },
            { type = "list_item", text = "Altar of Fangs", level = 0 },
            { type = "list_item", text = "Removed one High Evolutionist in the area after Rav'i.", level = 1 },
            { type = "list_item", text = "The Blinding Vale", level = 0 },
            { type = "list_item", text = "Increased enemy forces requirement to 686 (was 655).", level = 1 },
