        ["2026-08-25-class-tuning-incoming-august-25-8a01cf4496"] = {
            id = "2026-08-25-class-tuning-incoming-august-25-8a01cf4496",
            post_key = "8a01cf4496",
            title = "Class Tuning Incoming – August 25",
            category = "General Discussion (US)",
            timestamp = 1787616909,
            url = "https://us.forums.blizzard.com/en/wow/t/2339812/1",
            content = {
            { type = "p", text = "As we previously indicated, we’re doing broad class tuning each week for the first three weeks of the Curse of Ula’tek content update. With scheduled weekly maintenance in each region, we’ll make the following tuning adjustments." },
            { type = "h2", text = "CLASSES" },
            { type = "list_item", text = "Death Knight", level = 0 },
            { type = "dev_note", text = "Frost Death Knight has performed under our expectations at the beginning of Curse of Ula’tek, especially in the Venomous Abyss raid.", level = 1 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "list_item", text = "All ability damage and melee damage increased by 6%.", level = 2 },
            { type = "list_item", text = "Obliterate damage increased by 15%.", level = 2 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Vengeance", level = 1 },
            { type = "list_item", text = "Mastery: Fel Blood effectiveness increased by 24%.", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "These changes are intended to address Rejuvenation and Wild Growth feeling weak in season 2, particularly in dungeons. We’re also increasing the power of the 4-piece class set to make sure it’s an impactful and noticeable set bonus. These changes are accompanied by slight nerfs to their raid healing to keep them around the same power in raid while increasing their power in dungeons.", level = 2 },
            { type = "list_item", text = "4-piece class set bonus increases Genesis duration by 8 seconds (was 4 seconds).", level = 2 },
            { type = "list_item", text = "Rejuvenation and Germination healing increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wild Growth healing increased by 10%.", level = 2 },
            { type = "list_item", text = "Nature’s Bounty replicates 10% of Regrowth’s healing (was 20%).", level = 2 },
            { type = "list_item", text = "Everbloom heals 5 targets (was 6 targets).", level = 2 },
            { type = "list_item", text = "Everbloom heals for 48% of Lifebloom’s final heal (was 40%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Preservation", level = 1 },
            { type = "dev_note", text = "We’re further increasing some of the Preservation triage heals to help them keep up with other healers in dungeons.", level = 2 },
            { type = "list_item", text = "Verdant Embrace healing increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Living Flame healing increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Dream Simulacrum increases healing of Verdant Embrace by 40% (was 30%).", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Beast Mastery", level = 1 },
            { type = "dev_note", text = "We’re looking to increase Beast Mastery area damage and cleave capabilities.", level = 2 },
            { type = "list_item", text = "Wild Thrash now deals 300% increased damage when striking more than 2 targets (was 200%).", level = 2 },
            { type = "list_item", text = "Beast Cleave now causes your pets to strike nearby enemies for 70% of the damage dealt (was 55%).", level = 2 },
            { type = "list_item", text = "Survival", level = 1 },
            { type = "list_item", text = "All damage dealt by you and your pets increased by 4%.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "dev_note", text = "We’re primarily focused on Frost’s performance in Mythic Keystone dungeons. The recent removal of the health increase from Improved Ice Barrier had a greater effect on Frost’s overall survivability than intended. We like the symmetry of the three Improved Barrier talents having one additional effect, and Frost has historically had a slightly larger absorb than Arcane and Fire, so we’re baking it into the baseline absorb amount rather than re-attaching it to Improved Ice Barrier. We’re also making some targeted increases to Frost’s area of effect damage.", level = 2 },
            { type = "list_item", text = "Ice Barrier absorb amount increased to 35% of maximum health (was 30%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Blizzard damage increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostbite Talent: Shatter damage to nearby enemies increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostfire: Isothermic Core - Meteor damage increased by 25%.", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Brewmaster", level = 1 },
            { type = "list_item", text = "Developers’ note: We’re adjusting the absorption of Celestial Brew and Celestial Infusion to improve its impact as a defensive option and to help address pain points players are experiencing in some encounters.", level = 2 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Celestial Brew and Celestial Infusion absorb value increased by 20%.", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "We’re increasing the damage of the Curse of Ula’tek 4-piece set bonus Divine Arbiter significantly, to make sure its rotational ask is worth executing.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter main target damage increased by 150%.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter secondary target damage increased by 75%.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "dev_note", text = "We’re increasing the throughput of Affliction and Demonology by primarily focusing on their single-target tools with a secondary focus on their multi-target kit. Additionally, we’re considerably increasing the damage of Warlock demons so that they have a larger contribution to overall throughput. This should also help a bit more with aggro concerns during solo play.", level = 1 },
            { type = "list_item", text = "Imp, Voidwalker, Sayaad, and Felhunter damage increased by 350%.", level = 1 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Unstable Affliction damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Blackened Soul damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wrath of Nathreza damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow of Nathreza damage increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Corruption damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Wither damage increased by 10%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "list_item", text = "Shadow Bolt damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonbolt damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Wild Imp damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Summon Felguard damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demons summoned by Dominion of Argus damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Call Dreadstalkers damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Rain of Fire damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Fight Through the Flames reduces Magic damage by 8% (was 6%).", level = 2 },
            { type = "h2", text = "PLAYER VERSUS PLAYER" },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "dev_note", text = "We feel the defensive kits of Devourer and Havoc are too powerful, so we are reducing some of their passive and active defenses to make them more viable targets for opponents.", level = 1 },
            { type = "list_item", text = "Glimpse now reduces damage taken by 20% while active (was 25%).", level = 1 },
            { type = "list_item", text = "Devourer", level = 1 },
            { type = "list_item", text = "Void Ray damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Armor of Souls now increases Armor by 65% (was 100%).", level = 2 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Desperate Instincts now reduces damage taken by 5% while below 35% health in PvP combat (was 10%).", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Feral", level = 1 },
            { type = "dev_note", text = "Feral’s sustained damage is lower than our intended target, so we’re targeting their primary damage over time effects to improve this. We’re also targeting a buff for Druid of the Claw which has fallen behind Wildstalker in viability.", level = 2 },
            { type = "list_item", text = "Druid of the Claw: Ravage damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rip damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rake damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Augmentation", level = 1 },
            { type = "dev_note", text = "Augmentation has been underplayed in PvP, especially arenas, for some time. We’re increasing both their damage support capabilities and their personal damage to increase their viability.", level = 2 },
            { type = "list_item", text = "Damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Ebon Might grants 10% primary stat in PvP combat (was 8%).", level = 2 },
            { type = "list_item", text = "Inferno’s Blessing damage increased by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "dev_note", text = "Sentinel Hunters are slightly too strong during burst windows in PvP, so we’re reducing the damage of Moonlight Chakram and increasing the throughput of rotational abilities to compensate.", level = 1 },
            { type = "list_item", text = "Marksmanship", level = 1 },
            { type = "list_item", text = "Sentinel: Moonlight Chakram damage reduced by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rapid Fire damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Arcane Shot damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Survival", level = 1 },
            { type = "list_item", text = "Sentinel: Moonlight Chakram damage reduced by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Raptor Strike and Raptor Swipe damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Kill Command damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Fire", level = 1 },
            { type = "dev_note", text = "Fire Mage execute windows and hard cast Pyroblast damage have been higher than we would like, so we’re reducing the effectiveness of Molten Fury and Pyroclasm in PvP.", level = 2 },
            { type = "list_item", text = "Pyroclasm now increases the damage of Pyroblast and Flamestrike by 180% in PvP combat (was 230%).", level = 2 },
            { type = "list_item", text = "Molten Fury now increases damage to targets below 35% health by 10% in PvP combat (was 15%).", level = 2 },
            { type = "list_item", text = "Burnout now explodes for 50% of remaining Ignite damage in PvP combat (was 75%).", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Windwalker", level = 1 },
            { type = "list_item", text = "Rushing Wind Kick damage reduced by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rising Sun Kick damage reduced by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Tigereye Brew now increases critical strike damage by 3/6% in PvP combat (was 5/10%).", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "list_item", text = "Developer’s notes: Holy Paladin throughput has increased with recent changes past our targets for them in PvP.", level = 2 },
            { type = "list_item", text = "All healing reduced by 4% in PvP combat.", level = 2 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Developers’ note: Protection Paladins have been extending the duration of the matches that they participate in with frequent access to group utility. We’re reducing the effectiveness of Blessing of Sacrifice and Guardian of the Forgotten Queen to bring them in line.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen duration reduced to 6 seconds.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen cooldown increased to 4 minutes.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen now has a 6 second internal cooldown.", level = 2 },
            { type = "list_item", text = "Sacrifice of the Just reduces the cooldown of Blessing of Sacrifice by 30 seconds in PvP combat (was 60 seconds).", level = 2 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "Retribution’s personal durability has been higher than we would like considering their complete team defensive package, and Templar’s damage has not been competitive with Herald of the Sun, so we’re increasing some sources specific to its hero tree.", level = 2 },
            { type = "list_item", text = "Shield of Vengeance absorption reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Divine Protection now reduces damage taken by 20% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Templar: Seal of the Templar now increases the damage of Templar’s Verdict by 35% (was 25%).", level = 2 },
            { type = "list_item", text = "Templar: Hammer of Light’s damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "dev_note", text = "Mindgames has fallen behind other spells and has been an underutilized talent for some time, so we’re increasing its viability to offer all Priest specializations more PvP talent options.", level = 1 },
            { type = "list_item", text = "Mindgames direct damage increased by 150%.", level = 1 },
            { type = "list_item", text = "Mindgames healing and damage reversal increased by 150%.", level = 1 },
            { type = "list_item", text = "Discipline", level = 1 },
            { type = "list_item", text = "Flash Heal and Shadow Mend healing increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Atonement healing increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "dev_note", text = "Holy Priest is vastly overperforming due to a mixture of overall healing increases from the patch as well as some generous PvP specific healing increases to Prayer of Mending and Holy Word: Serenity. We’re reducing these PvP increases to Prayer of Mending, Holy Word: Serenity, and Prompt Prognosis which are all powerful instant cast spells.", level = 2 },
            { type = "list_item", text = "Enlightenment regenerates mana 10% faster in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Prayer of Mending healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy Word: Serenity healing reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Oracle: Prompt Prognosis healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow", level = 1 },
            { type = "dev_note", text = "We feel Shadow is lacking in kill power, so we’re increasing some of its primary sources of burst.", level = 2 },
            { type = "list_item", text = "Shadow Word: Madness damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Void Volley damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow Word: Death damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rogue", level = 0 },
            { type = "list_item", text = "Assassination", level = 1 },
            { type = "dev_note", text = "Burst from Assassination’s Apex Talent is exceeding expectations and is getting toned down. Additionally, damage from Fatebound Coins is higher than intended and is being reduced.", level = 2 },
            { type = "list_item", text = "Kingsbane initial damage reduced by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Implacable (Rank 3) Physical and Nature damage reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fatebound: Fatebound Coin (Tails) damage reduced by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Outlaw", level = 1 },
            { type = "dev_note", text = "Outlaw’s damage and kill pressure is lower than we’d expect, so we’re putting more damage into core finishing moves.", level = 2 },
            { type = "list_item", text = "Dispatch damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Between the Eyes damage increased by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Subtlety", level = 1 },
            { type = "dev_note", text = "Subtlety’s steady damage pressure is low, without which it can be difficult to create windows that capitalize on their burst potential. We’re increasing * Eviscerate damage moderately and Goremaw’s Bite bleed damage significantly to increase the frequency of these windows.", level = 2 },
            { type = "list_item", text = "Eviscerate damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Goremaw’s Bite bleeding damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Elemental", level = 1 },
            { type = "dev_note", text = "Elemental is lacking the sustained pressure we expect, so we’re targeting core damage sources to improve its viability. Stormbringer: Tempest damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Lava Burst damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earth Shock damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earthquake damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "Restoration Shaman is slightly too strong compared to other healers (barring Holy Priest). We’re making some small adjustments to their mana and the Totemic hero talent tree to better balance their mana and throughput.", level = 2 },
            { type = "list_item", text = "Mana regeneration is now reduced by 65% in PvP combat (was 60%).", level = 2 },
            { type = "list_item", text = "Totemic: Splitstream now causes Healing Stream Totem to heal an additional ally at 15% effectiveness in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Totemic: Earthsurge now causes allies affected by your Earthliving to receive 5% additional healing from you in PvP combat (was 15%).", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "dev_note", text = "We’re increasing Affliction’s ability to maintain spread pressure by adjusting Agony’s damage and making a small adjustment to Unstable Affliction’s backlash damage to make dispelling all their damage over time effects more punishing.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Unstable Affliction backlash damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "dev_note", text = "We feel too much of Demonology’s damage is focused on Wicked Reaping and Power Siphon, so we’re reducing the power of these effects and increasing overall damage through our game-wide Demonology changes above.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Wicked Reaping damage reduced by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Necrolyte Teachings now causes Power Siphon to increase the damage of Demonbolt by an additional 10% in PvP combat (was 20%).", level = 2 },
            { type = "list_item", text = "Power Siphon now increases the damage of your next 2 Demonbolts by 20% in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "dev_note", text = "Destruction is lacking in finishing power, so we’re increasing the damage of their primary nuke spells to allow for more burst potential.", level = 2 },
            { type = "list_item", text = "Chaos Bolt damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadowburn damage increased by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Arms", level = 1 },
            { type = "dev_note", text = "To compensate for the reduction in Fueled by Violence self-healing, we’re increasing Arms’ Hero Talents throughput by increasing Slayer’s Strike and Demolish damage in PvP.", level = 2 },
            { type = "list_item", text = "Colossus: Demolish damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Slayer: Slayer’s Strike damage increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fueled by Violence healing reduced by 15% in PvP combat.", level = 2 },
            },
        },
        ["2026-08-24-new-raids-open-at-300-pm-pdt-on-august-27-e699b5b7d5"] = {
            id = "2026-08-24-new-raids-open-at-300-pm-pdt-on-august-27-e699b5b7d5",
            post_key = "e699b5b7d5",
            title = "New Raids Open at 3:00 p.m. PDT on August 27",
            category = "The Burning Crusade Classic (US)",
            timestamp = 1787610609,
            url = "https://us.forums.blizzard.com/en/wow/t/2340643/1",
            content = {
            { type = "p", text = "First and foremost, we’d like to thank everyone who participated in raid testing on the PTR. Thanks to your testing, we were able to identify and fix several issues, including the first wave of attackers for the Horde base sometimes de-spawning, the wave counter UI at the top of the screen disappearing, and some boss abilities incorrectly targeting the tank." },
            { type = "p", text = "We’re also adding extra tier token drops to bosses, just like we did previously. That increase was not on the PTR, but will be in place when the new raids open on Thursday, August 27 at 3:00 p.m. PDT (6:00 p.m. EDT)." },
            { type = "p", text = "One question we saw a bit was asking for clarity on our previously-posted statement “We will plan to make other Phase 3 loot changes to heroic dungeon bosses in Phase 3.” As some players correctly concluded, that was intended to call out the Phase 3 changes that players are already familiar with, such as the Epic Gems. We do not have any surprise additional loot changes in the works." },
            { type = "p", text = "As a reminder, Arena Season 3 starts with the weekly reset next week – that’s the morning of September 1 in this region." },
            { type = "p", text = "We’ll see you there!" },
            },
        },
        ["2026-08-24-class-tuning-incoming-26-august-fc37ef1749"] = {
            id = "2026-08-24-class-tuning-incoming-26-august-fc37ef1749",
            post_key = "fc37ef1749",
            title = "Class Tuning Incoming – 26 August",
            category = "General Discussion (EU)",
            timestamp = 1787608808,
            url = "https://eu.forums.blizzard.com/en/wow/t/626484/1",
            content = {
            { type = "p", text = "As we previously indicated, we’re doing broad class tuning each week for the first three weeks of the Curse of Ula’tek content update. With scheduled weekly maintenance in each region, we’ll make the following tuning adjustments." },
            { type = "h2", text = "CLASSES" },
            { type = "list_item", text = "Death Knight", level = 0 },
            { type = "dev_note", text = "Frost Death Knight has performed under our expectations at the beginning of Curse of Ula’tek, especially in the Venomous Abyss raid.", level = 1 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "list_item", text = "All ability damage and melee damage increased by 6%.", level = 2 },
            { type = "list_item", text = "Obliterate damage increased by 15%.", level = 2 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Vengeance", level = 1 },
            { type = "list_item", text = "Mastery: Fel Blood effectiveness increased by 24%.", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "These changes are intended to address Rejuvenation and Wild Growth feeling weak in season 2, particularly in dungeons. We’re also increasing the power of the 4-piece class set to make sure it’s an impactful and noticeable set bonus. These changes are accompanied by slight nerfs to their raid healing to keep them around the same power in raid while increasing their power in dungeons.", level = 2 },
            { type = "list_item", text = "4-piece class set bonus increases Genesis duration by 8 seconds (was 4 seconds).", level = 2 },
            { type = "list_item", text = "Rejuvenation and Germination healing increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wild Growth healing increased by 10%.", level = 2 },
            { type = "list_item", text = "Nature’s Bounty replicates 10% of Regrowth’s healing (was 20%).", level = 2 },
            { type = "list_item", text = "Everbloom heals 5 targets (was 6 targets).", level = 2 },
            { type = "list_item", text = "Everbloom heals for 48% of Lifebloom’s final heal (was 40%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Preservation", level = 1 },
            { type = "dev_note", text = "We’re further increasing some of the Preservation triage heals to help them keep up with other healers in dungeons.", level = 2 },
            { type = "list_item", text = "Verdant Embrace healing increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Living Flame healing increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Dream Simulacrum increases healing of Verdant Embrace by 40% (was 30%).", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Beast Mastery", level = 1 },
            { type = "dev_note", text = "We’re looking to increase Beast Mastery area damage and cleave capabilities.", level = 2 },
            { type = "list_item", text = "Wild Thrash now deals 300% increased damage when striking more than 2 targets (was 200%).", level = 2 },
            { type = "list_item", text = "Beast Cleave now causes your pets to strike nearby enemies for 70% of the damage dealt (was 55%).", level = 2 },
            { type = "list_item", text = "Survival", level = 1 },
            { type = "list_item", text = "All damage dealt by you and your pets increased by 4%.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Frost", level = 1 },
            { type = "dev_note", text = "We’re primarily focused on Frost’s performance in Mythic Keystone dungeons. The recent removal of the health increase from Improved Ice Barrier had a greater effect on Frost’s overall survivability than intended. We like the symmetry of the three Improved Barrier talents having one additional effect, and Frost has historically had a slightly larger absorb than Arcane and Fire, so we’re baking it into the baseline absorb amount rather than re-attaching it to Improved Ice Barrier. We’re also making some targeted increases to Frost’s area of effect damage.", level = 2 },
            { type = "list_item", text = "Ice Barrier absorb amount increased to 35% of maximum health (was 30%). Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Blizzard damage increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostbite Talent: Shatter damage to nearby enemies increased by 10%.", level = 2 },
            { type = "list_item", text = "Frostfire: Isothermic Core - Meteor damage increased by 25%.", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Brewmaster", level = 1 },
            { type = "list_item", text = "Developers’ note: We’re adjusting the absorption of Celestial Brew and Celestial Infusion to improve its impact as a defensive option and to help address pain points players are experiencing in some encounters.", level = 2 },
            { type = "list_item", text = "All damage increased by 3%.", level = 2 },
            { type = "list_item", text = "Celestial Brew and Celestial Infusion absorb value increased by 20%.", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "We’re increasing the damage of the Curse of Ula’tek 4-piece set bonus Divine Arbiter significantly, to make sure its rotational ask is worth executing.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter main target damage increased by 150%.", level = 2 },
            { type = "list_item", text = "Class Set 4-piece Divine Arbiter secondary target damage increased by 75%.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "dev_note", text = "We’re increasing the throughput of Affliction and Demonology by primarily focusing on their single-target tools with a secondary focus on their multi-target kit. Additionally, we’re considerably increasing the damage of Warlock demons so that they have a larger contribution to overall throughput. This should also help a bit more with aggro concerns during solo play.", level = 1 },
            { type = "list_item", text = "Imp, Voidwalker, Sayaad, and Felhunter damage increased by 350%.", level = 1 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Unstable Affliction damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Blackened Soul damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Wrath of Nathreza damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow of Nathreza damage increased by 25%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Corruption damage increased by 15%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Hellcaller – Wither damage increased by 10%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "list_item", text = "Shadow Bolt damage increased by 35%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Demonbolt damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Wild Imp damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Summon Felguard damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demons summoned by Dominion of Argus damage increased by 20%. Does not apply to PvP combat.", level = 2 },
            { type = "list_item", text = "Call Dreadstalkers damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Rain of Fire damage increased by 30%.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Fight Through the Flames reduces Magic damage by 8% (was 6%).", level = 2 },
            { type = "h2", text = "PLAYER VERSUS PLAYER" },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "dev_note", text = "We feel the defensive kits of Devourer and Havoc are too powerful, so we are reducing some of their passive and active defenses to make them more viable targets for opponents.", level = 1 },
            { type = "list_item", text = "Glimpse now reduces damage taken by 20% while active (was 25%).", level = 1 },
            { type = "list_item", text = "Devourer", level = 1 },
            { type = "list_item", text = "Void Ray damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Armor of Souls now increases Armor by 65% (was 100%).", level = 2 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "Blur now reduces damage taken by 15% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Desperate Instincts now reduces damage taken by 5% while below 35% health in PvP combat (was 10%).", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Feral", level = 1 },
            { type = "dev_note", text = "Feral’s sustained damage is lower than our intended target, so we’re targeting their primary damage over time effects to improve this. We’re also targeting a buff for Druid of the Claw which has fallen behind Wildstalker in viability.", level = 2 },
            { type = "list_item", text = "Druid of the Claw: Ravage damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rip damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rake damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Augmentation", level = 1 },
            { type = "dev_note", text = "Augmentation has been underplayed in PvP, especially arenas, for some time. We’re increasing both their damage support capabilities and their personal damage to increase their viability.", level = 2 },
            { type = "list_item", text = "Damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Ebon Might grants 10% primary stat in PvP combat (was 8%).", level = 2 },
            { type = "list_item", text = "Inferno’s Blessing damage increased by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "dev_note", text = "Sentinel Hunters are slightly too strong during burst windows in PvP, so we’re reducing the damage of Moonlight Chakram and increasing the throughput of rotational abilities to compensate.", level = 1 },
            { type = "list_item", text = "Marksmanship", level = 1 },
            { type = "list_item", text = "Sentinel: Moonlight Chakram damage reduced by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rapid Fire damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Arcane Shot damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Survival", level = 1 },
            { type = "list_item", text = "Sentinel: Moonlight Chakram damage reduced by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Raptor Strike and Raptor Swipe damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Kill Command damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Fire", level = 1 },
            { type = "dev_note", text = "Fire Mage execute windows and hard cast Pyroblast damage have been higher than we would like, so we’re reducing the effectiveness of Molten Fury and Pyroclasm in PvP.", level = 2 },
            { type = "list_item", text = "Pyroclasm now increases the damage of Pyroblast and Flamestrike by 180% in PvP combat (was 230%).", level = 2 },
            { type = "list_item", text = "Molten Fury now increases damage to targets below 35% health by 10% in PvP combat (was 15%).", level = 2 },
            { type = "list_item", text = "Burnout now explodes for 50% of remaining Ignite damage in PvP combat (was 75%).", level = 2 },
            { type = "list_item", text = "Monk", level = 0 },
            { type = "list_item", text = "Windwalker", level = 1 },
            { type = "list_item", text = "Rushing Wind Kick damage reduced by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rising Sun Kick damage reduced by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Tigereye Brew now increases critical strike damage by 3/6% in PvP combat (was 5/10%).", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "list_item", text = "Developer’s notes: Holy Paladin throughput has increased with recent changes past our targets for them in PvP.", level = 2 },
            { type = "list_item", text = "All healing reduced by 4% in PvP combat.", level = 2 },
            { type = "list_item", text = "Protection", level = 1 },
            { type = "list_item", text = "Developers’ note: Protection Paladins have been extending the duration of the matches that they participate in with frequent access to group utility. We’re reducing the effectiveness of Blessing of Sacrifice and Guardian of the Forgotten Queen to bring them in line.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen duration reduced to 6 seconds.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen cooldown increased to 4 minutes.", level = 2 },
            { type = "list_item", text = "Guardian of the Forgotten Queen now has a 6 second internal cooldown.", level = 2 },
            { type = "list_item", text = "Sacrifice of the Just reduces the cooldown of Blessing of Sacrifice by 30 seconds in PvP combat (was 60 seconds).", level = 2 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "Retribution’s personal durability has been higher than we would like considering their complete team defensive package, and Templar’s damage has not been competitive with Herald of the Sun, so we’re increasing some sources specific to its hero tree.", level = 2 },
            { type = "list_item", text = "Shield of Vengeance absorption reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Divine Protection now reduces damage taken by 20% in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Templar: Seal of the Templar now increases the damage of Templar’s Verdict by 35% (was 25%).", level = 2 },
            { type = "list_item", text = "Templar: Hammer of Light’s damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "dev_note", text = "Mindgames has fallen behind other spells and has been an underutilized talent for some time, so we’re increasing its viability to offer all Priest specializations more PvP talent options.", level = 1 },
            { type = "list_item", text = "Mindgames direct damage increased by 150%.", level = 1 },
            { type = "list_item", text = "Mindgames healing and damage reversal increased by 150%.", level = 1 },
            { type = "list_item", text = "Discipline", level = 1 },
            { type = "list_item", text = "Flash Heal and Shadow Mend healing increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Atonement healing increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "dev_note", text = "Holy Priest is vastly overperforming due to a mixture of overall healing increases from the patch as well as some generous PvP specific healing increases to Prayer of Mending and Holy Word: Serenity. We’re reducing these PvP increases to Prayer of Mending, Holy Word: Serenity, and Prompt Prognosis which are all powerful instant cast spells.", level = 2 },
            { type = "list_item", text = "Enlightenment regenerates mana 10% faster in PvP combat (was 25%).", level = 2 },
            { type = "list_item", text = "Prayer of Mending healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Holy Word: Serenity healing reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Oracle: Prompt Prognosis healing reduced by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow", level = 1 },
            { type = "dev_note", text = "We feel Shadow is lacking in kill power, so we’re increasing some of its primary sources of burst.", level = 2 },
            { type = "list_item", text = "Shadow Word: Madness damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Void Volley damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadow Word: Death damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Rogue", level = 0 },
            { type = "list_item", text = "Assassination", level = 1 },
            { type = "dev_note", text = "Burst from Assassination’s Apex Talent is exceeding expectations and is getting toned down. Additionally, damage from Fatebound Coins is higher than intended and is being reduced.", level = 2 },
            { type = "list_item", text = "Kingsbane initial damage reduced by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Implacable (Rank 3) Physical and Nature damage reduced by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fatebound: Fatebound Coin (Tails) damage reduced by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Outlaw", level = 1 },
            { type = "dev_note", text = "Outlaw’s damage and kill pressure is lower than we’d expect, so we’re putting more damage into core finishing moves.", level = 2 },
            { type = "list_item", text = "Dispatch damage increased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Between the Eyes damage increased by 12% in PvP combat.", level = 2 },
            { type = "list_item", text = "Subtlety", level = 1 },
            { type = "dev_note", text = "Subtlety’s steady damage pressure is low, without which it can be difficult to create windows that capitalize on their burst potential. We’re increasing * Eviscerate damage moderately and Goremaw’s Bite bleed damage significantly to increase the frequency of these windows.", level = 2 },
            { type = "list_item", text = "Eviscerate damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Goremaw’s Bite bleeding damage increased by 33% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Elemental", level = 1 },
            { type = "dev_note", text = "Elemental is lacking the sustained pressure we expect, so we’re targeting core damage sources to improve its viability. Stormbringer: Tempest damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Lava Burst damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earth Shock damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Earthquake damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "Restoration Shaman is slightly too strong compared to other healers (barring Holy Priest). We’re making some small adjustments to their mana and the Totemic hero talent tree to better balance their mana and throughput.", level = 2 },
            { type = "list_item", text = "Mana regeneration is now reduced by 65% in PvP combat (was 60%).", level = 2 },
            { type = "list_item", text = "Totemic: Splitstream now causes Healing Stream Totem to heal an additional ally at 15% effectiveness in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Totemic: Earthsurge now causes allies affected by your Earthliving to receive 5% additional healing from you in PvP combat (was 15%).", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "dev_note", text = "We’re increasing Affliction’s ability to maintain spread pressure by adjusting Agony’s damage and making a small adjustment to Unstable Affliction’s backlash damage to make dispelling all their damage over time effects more punishing.", level = 2 },
            { type = "list_item", text = "Agony damage increased by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Unstable Affliction backlash damage increased by 20%.", level = 2 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "dev_note", text = "We feel too much of Demonology’s damage is focused on Wicked Reaping and Power Siphon, so we’re reducing the power of these effects and increasing overall damage through our game-wide Demonology changes above.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Wicked Reaping damage reduced by 50% in PvP combat.", level = 2 },
            { type = "list_item", text = "Soul Harvester: Necrolyte Teachings now causes Power Siphon to increase the damage of Demonbolt by an additional 10% in PvP combat (was 20%).", level = 2 },
            { type = "list_item", text = "Power Siphon now increases the damage of your next 2 Demonbolts by 20% in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "dev_note", text = "Destruction is lacking in finishing power, so we’re increasing the damage of their primary nuke spells to allow for more burst potential.", level = 2 },
            { type = "list_item", text = "Chaos Bolt damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Shadowburn damage increased by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Arms", level = 1 },
            { type = "dev_note", text = "To compensate for the reduction in Fueled by Violence self-healing, we’re increasing Arms’ Hero Talents throughput by increasing Slayer’s Strike and Demolish damage in PvP.", level = 2 },
            { type = "list_item", text = "Colossus: Demolish damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Slayer: Slayer’s Strike damage increased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Fueled by Violence healing reduced by 15% in PvP combat.", level = 2 },
            },
        },
        ["2026-08-24-new-raids-open-at-2359-cest-on-august-27-8769974689"] = {
            id = "2026-08-24-new-raids-open-at-2359-cest-on-august-27-8769974689",
            post_key = "8769974689",
            title = "New Raids Open at 23:59 CEST on August 27",
            category = "The Burning Crusade Classic (EU)",
            timestamp = 1787595313,
            url = "https://eu.forums.blizzard.com/en/wow/t/626698/1",
            content = {
            { type = "p", text = "First and foremost, we’d like to thank everyone who participated in raid testing on the PTR. Thanks to your testing, we were able to identify and fix several issues, including the first wave of attackers for the Horde base sometimes de-spawning, the wave counter UI at the top of the screen disappearing, and some boss abilities incorrectly targeting the tank." },
            { type = "p", text = "We’re also adding extra tier token drops to bosses, just like we did previously. That increase was not on the PTR, but will be in place when the new raids open on Thursday, August 27 at 23:59 CEST." },
            { type = "p", text = "One question we saw a bit was asking for clarity on our previously-posted statement “We will plan to make other Phase 3 loot changes to heroic dungeon bosses in Phase 3.” As some players correctly concluded, that was intended to call out the Phase 3 changes that players are already familiar with, such as the Epic Gems. We do not have any surprise additional loot changes in the works." },
            { type = "p", text = "As a reminder, Arena Season 3 starts with the weekly reset next week – that’s the morning of September 2 in this region." },
            { type = "p", text = "We’ll see you there!" },
            },
        },
        ["2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8"] = {
            id = "2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8",
            post_key = "b230ed3bb8",
            title = "September is a Great Month to Celebrate Friendship at the Trading Post",
            category = "Blogs (EU)",
            timestamp = 1787591720,
            url = "https://news.blizzard.com/en-gb/article/24295383/september-is-a-great-month-to-celebrate-friendship-at-the-trading-post",
            content = {
            { type = "p", text = "Friendship takes center stage at the Trading Post this September as Azeroth celebrates BlizzCon 2026. Ride into your adventures with chameleon-like grace on the Crested Ember Leafmimic mount and visit special Outlet vendors in Dornogal and Silvermoon City featuring discounted and returning items." },
            { type = "hr" },
            { type = "image", width = 720, height = 387, u = 0.703125, v = 0.755859, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-1.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-2.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-3.jpg" },
            { type = "p", text = "Visit T&W** (Tawney and Wilder) just outside the Mage District in Stormwind or the Zen’shiri Trading Post next to Grommash Hold in Orgrimmar to check out all the latest items*** they have available. Players can also visit the Trading Post in the capital city of Dornogal (The Foregrounds) on the Isle of Dorn, where representatives of both Tawney and Wilder and the Zen’shiri Trading Post are open for business." },
            { type = "hr" },
            { type = "h3", text = "Check Out What's in Stock for September" },
            { type = "image", width = 666, height = 420, u = 0.650391, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-4.jpg" },
            { type = "p", text = "Crested Verdant Leafmimic Mount“Found primarily in areas with dense vegetation, this leafmimic is rarely spotted due to the natural hues of its scales, allowing it to blend in with its surroundings.”" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-5.jpg" },
            { type = "p", text = "Gummi Pet“Gummi baubleworms have an abundance of natural predators, as they are known for their rubbery texture and sweet flavors.”" },
            { type = "p", text = "This month, the previous promotional pet, Gummi, arrives on the Trading Post for the first time." },
            { type = "h2", text = "MOUNTS AND PETS" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "hr" },
            { type = "h2", text = "ARMOR TRANSMOG APPEARANCES" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "hr" },
            { type = "h2", text = "WEAPON TRANSMOG APPEARANCES" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-6.jpg" },
            { type = "p", text = "Grand Pyrestone War Axe Two-Hand Axe“The razor edge of the pyrestone head gleams like the skies over Blade's Edge Mountains.”" },
            { type = "h3", text = "Item Name" },
            { type = "h3", text = "Item Type" },
            { type = "h3", text = "Cost" },
            { type = "hr" },
            { type = "h3", text = "This Month's Bonus Reward" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-7.jpg" },
            { type = "p", text = "Crested Ember Leafmimic Mount“This sturdy leafmimic can be found only in the warmest of areas. Its red scales allow it to hide undiscovered in the heated alcoves it prefers.”" },
            { type = "p", text = "Complete activities to fill the bar at the top of the Traveler’s Log found in the Adventure Guide (Shift-J)***, and you'll receive this month's bonus reward—the Crested Ember Leafmimic mount." },
            { type = "hr" },
            { type = "h3", text = "Visit the Trading Post Outlet" },
            { type = "p", text = "To commemorate BlizzCon 2026, visit the Trading Post in Dornogal and in the capital city of Silvermoon City, where representatives of both Tawney and Wilder and the Zen’shiri Trading Post are open for business. You’ll find a cache of treasures from previous stall offerings with the return of many mounts, pets, toys, armor transmogs, and weapon transmogs, as they make their way into the Trading Post once more." },
            { type = "p", text = "If you missed them the first time around, you can also purchase previous Monthly Bonus rewards for the first time with Trader’s Tender." },
            { type = "list_item", text = "Monthly Bonus Items", level = 0 },
            { type = "list_item", text = "Pets, Mounts, and Toys", level = 0 },
            { type = "list_item", text = "Armor Transmog Appearances", level = 0 },
            { type = "list_item", text = "Weapon Transmog Appearances", level = 0 },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-8.jpg" },
            { type = "p", text = "Crusty Crawler Mount" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-9.jpg" },
            { type = "p", text = "Arsenal: Crests of the Kingdom Back (Orc, Night Elf, Scourge, and Human Crests)" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-10.jpg" },
            { type = "p", text = "Claudius Pet" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-11.jpg" },
            { type = "p", text = "Colorful Beach Chair Toy" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-12.jpg" },
            { type = "p", text = "Frenzied Hat of the Murky Waters Head" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-13.jpg" },
            { type = "p", text = "Plunderlord's Radiant Finery Head, Chest, Back, Shoulders, Waist, Wrist, Legs, Hands, Feet" },
            { type = "h3", text = "Item Name" },
            { type = "h3", text = "Item Type" },
            { type = "h3", text = "Cost" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-14.jpg" },
            { type = "p", text = "Plunderlord's Radiant Sigil Staff" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-b230ed3bb8\\image-15.jpg" },
            { type = "p", text = "Ruby Felfire Splitblade One-Hand Sword" },
            { type = "h3", text = "Item Name" },
            { type = "h3", text = "Item Type" },
            { type = "h3", text = "Cost" },
            { type = "hr" },
            { type = "h2", text = "HOW IT WORKS" },
            { type = "h3", text = "Get Tender Every Month" },
            { type = "p", text = "At the beginning of each month, players with an active account in good standing will receive 500 Trader’s Tender automatically every month from a chest called the Collector’s Cache. If you don’t have active game time on your account or aren’t a subscriber at the start of a new month, don’t worry. Your Tender will be awarded on the first day of the month when you do have game time or an active subscription. This will be the same amount for everyone, regardless of how you pay for your game time." },
            { type = "h3", text = "The Traveler's Log" },
            { type = "p", text = "Complete monthly activities listed in the new Traveler’s Log. Each month features a rotating, themed set of activities. These activities provide the opportunity to earn up to 500 additional Trader’s Tender. There’s only a set amount of Tender you can earn each month through completing activities, so you won’t need to complete all the ones in the log each month. You’ll be able to pick and choose from a variety of fun in-game activities to easily earn Tender. Players can choose to earn by continuing to play the game as they already do, such as completing quests, competing in battlegrounds, participating in holiday activities, and even running Mythic+ dungeons. But you can also choose to take part in activities uniquely designed for the month." },
            { type = "h3", text = "Freeze an Item" },
            { type = "p", text = "Before the month comes to an end, if you haven’t purchased that one “must-have” item yet, don’t worry. You can “freeze” an item so you can purchase it later. When you freeze an item, it will stay available month over month until it is purchased or replaced." },
            { type = "p", text = "If this month’s offerings didn’t have the items you wanted, you can hang on to your Trader’s Tender to spend later. It won’t go anywhere, and unspent Tender will continue to accumulate each month." },
            { type = "hr" },
            { type = "p", text = "Learn more about the Trading Post from the news post on the official site." },
            { type = "p", text = "*The Trading Post feature is not available in WoW Classic titles.**Requires World of Warcraft Subscription or Game Time***Requires Level 10 to access the Adventure Guide." },
            },
        },
        ["2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb"] = {
            id = "2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb",
            post_key = "ae182020cb",
            title = "September is a Great Month to Celebrate Friendship at the Trading Post",
            category = "Blogs (US)",
            timestamp = 1787591716,
            url = "https://news.blizzard.com/en-us/article/24295383/september-is-a-great-month-to-celebrate-friendship-at-the-trading-post",
            content = {
            { type = "p", text = "Friendship takes center stage at the Trading Post this September as Azeroth celebrates BlizzCon 2026. Ride into your adventures with chameleon-like grace on the Crested Ember Leafmimic mount and visit special Outlet vendors in Dornogal and Silvermoon City featuring discounted and returning items." },
            { type = "hr" },
            { type = "image", width = 720, height = 387, u = 0.703125, v = 0.755859, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-1.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-2.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-3.jpg" },
            { type = "p", text = "Visit T&W** (Tawney and Wilder) just outside the Mage District in Stormwind or the Zen’shiri Trading Post next to Grommash Hold in Orgrimmar to check out all the latest items*** they have available. Players can also visit the Trading Post in the capital city of Dornogal (The Foregrounds) on the Isle of Dorn, where representatives of both Tawney and Wilder and the Zen’shiri Trading Post are open for business." },
            { type = "hr" },
            { type = "h3", text = "Check Out What's in Stock for September" },
            { type = "image", width = 666, height = 420, u = 0.650391, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-4.jpg" },
            { type = "p", text = "Crested Verdant Leafmimic Mount“Found primarily in areas with dense vegetation, this leafmimic is rarely spotted due to the natural hues of its scales, allowing it to blend in with its surroundings.”" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-5.jpg" },
            { type = "p", text = "Gummi Pet“Gummi baubleworms have an abundance of natural predators, as they are known for their rubbery texture and sweet flavors.”" },
            { type = "p", text = "This month, the previous promotional pet, Gummi, arrives on the Trading Post for the first time." },
            { type = "h2", text = "MOUNTS AND PETS" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "hr" },
            { type = "h2", text = "ARMOR TRANSMOG APPEARANCES" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "hr" },
            { type = "h2", text = "WEAPON TRANSMOG APPEARANCES" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-6.jpg" },
            { type = "p", text = "Grand Pyrestone War Axe Two-Hand Axe“The razor edge of the pyrestone head gleams like the skies over Blade's Edge Mountains.”" },
            { type = "h3", text = "Item Name" },
            { type = "h3", text = "Item Type" },
            { type = "h3", text = "Cost" },
            { type = "hr" },
            { type = "h3", text = "This Month's Bonus Reward" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-7.jpg" },
            { type = "p", text = "Crested Ember Leafmimic Mount“This sturdy leafmimic can be found only in the warmest of areas. Its red scales allow it to hide undiscovered in the heated alcoves it prefers.”" },
            { type = "p", text = "Complete activities to fill the bar at the top of the Traveler’s Log found in the Adventure Guide (Shift-J)***, and you'll receive this month's bonus reward—the Crested Ember Leafmimic mount." },
            { type = "hr" },
            { type = "h3", text = "Visit the Trading Post Outlet" },
            { type = "p", text = "To commemorate BlizzCon 2026, visit the Trading Post in Dornogal and in the capital city of Silvermoon City, where representatives of both Tawney and Wilder and the Zen’shiri Trading Post are open for business. You’ll find a cache of treasures from previous stall offerings with the return of many mounts, pets, toys, armor transmogs, and weapon transmogs, as they make their way into the Trading Post once more." },
            { type = "p", text = "If you missed them the first time around, you can also purchase previous Monthly Bonus rewards for the first time with Trader’s Tender." },
            { type = "list_item", text = "Monthly Bonus Items", level = 0 },
            { type = "list_item", text = "Pets, Mounts, and Toys", level = 0 },
            { type = "list_item", text = "Armor Transmog Appearances", level = 0 },
            { type = "list_item", text = "Weapon Transmog Appearances", level = 0 },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-8.jpg" },
            { type = "p", text = "Crusty Crawler Mount" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-9.jpg" },
            { type = "p", text = "Arsenal: Crests of the Kingdom Back (Orc, Night Elf, Scourge, and Human Crests)" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Cost" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-10.jpg" },
            { type = "p", text = "Claudius Pet" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-11.jpg" },
            { type = "p", text = "Colorful Beach Chair Toy" },
