            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-12.jpg" },
            { type = "p", text = "Frenzied Hat of the Murky Waters Head" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-13.jpg" },
            { type = "p", text = "Plunderlord's Radiant Finery Head, Chest, Back, Shoulders, Waist, Wrist, Legs, Hands, Feet" },
            { type = "h3", text = "Item Name" },
            { type = "h3", text = "Item Type" },
