            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-14.jpg" },
            { type = "p", text = "Plunderlord's Radiant Sigil Staff" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-24-september-is-a-great-month-to-celebrate-friendship-at-the-trading-post-ae182020cb\\image-15.jpg" },
            { type = "p", text = "Ruby Felfire Splitblade One-Hand Sword" },
