        ["2026-08-23-nymrissa-wavecaller-tuning-changes-a26a926645"] = {
            id = "2026-08-23-nymrissa-wavecaller-tuning-changes-a26a926645",
            post_key = "a26a926645",
            title = "Nymrissa Wavecaller Tuning Changes",
            category = "Dungeons, Raids and Scenarios (US)",
            timestamp = 1787448611,
            url = "https://us.forums.blizzard.com/en/wow/t/2340109/1",
            content = {
            { type = "p", text = "Hello," },
            { type = "p", text = "We just sent a hotfix with the following changes to Nymrissa Wavecaller on Mythic difficulty:" },
            { type = "list_item", text = "Abyssal Rain’s initial damage reduced by 12.5% on Mythic difficulty", level = 0 },
            { type = "list_item", text = "Abyssal Rain’s periodic damage reduced by 20% on Mythic difficulty", level = 0 },
            { type = "list_item", text = "Reduced Abyssal Rain’s damage scaling based on group size for larger groups", level = 0 },
            { type = "list_item", text = "Frost Burst damage reduced by 40%", level = 0 },
            },
        },
        ["2026-08-22-hotfixes-august-21-2026-e0dc8eb65c"] = {
            id = "2026-08-22-hotfixes-august-21-2026-e0dc8eb65c",
            post_key = "e0dc8eb65c",
            title = "Hotfixes: August 21, 2026",
            category = "Blogs (EU)",
            timestamp = 1787364038,
            url = "https://news.blizzard.com/en-gb/article/24296142/hotfixes-august-21-2026",
            content = {
            { type = "p", text = "Here you'll find a list of hotfixes that address various issues related to World of Warcraft: Midnight, Mists of Pandaria Classic, Season of Discovery, Burning Crusade Classic, WoW Classic Era, and Hardcore. Some of the hotfixes below take effect the moment they were implemented, while others may require scheduled realm restarts to go into effect. Please keep in mind that some issues cannot be addressed without a client-side patch update. This list will be updated as additional hotfixes are applied." },
            { type = "h2", text = "HOTFIXES" },
            { type = "hr" },
            { type = "h3", text = "August 21, 2026" },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "Phantasmal Spore Toxin and Frostheart Venom will now properly be removed when leaving the delve.", level = 0 },
            { type = "list_item", text = "Illusory Deceit no longer incorrectly scales the number of Twilight Illusions based on the number of players during Infiltrator Gulkat's encounter in The Darkway.", level = 0 },
            { type = "list_item", text = "Players may now only pick up and carry one Oddball Ingredient at a time.", level = 0 },
            { type = "h3", text = "Dungeons and Raids" },
            { type = "list_item", text = "Altar of Fangs", level = 0 },
            { type = "list_item", text = "Ravenous Descendant’s Ravenous now grants 10% attack speed per stack (was 20%), and movement speed reduced by 20%.", level = 1 },
            { type = "list_item", text = "Twinfang Harrower’s Paralyzing Shots initial damage reduced by 50%.", level = 1 },
            { type = "list_item", text = "Venom Leech’s Septic Spatter no longer creates a puddle at the leech’s corpse location.", level = 1 },
            { type = "list_item", text = "Ritual Chieftain’s Blood Sacrifice absorb reduced by 10%.", level = 1 },
            { type = "list_item", text = "Caustic Mist Totem’s Unstable Totem damage reduced by 10%.", level = 1 },
            { type = "list_item", text = "High Evolutionist’s Evolve cooldown increased, Envenom cast time increased to 3 seconds (was 2.5 seconds), and Mass Envenom cast time increased to 3.5 seconds (was 2.5 seconds).", level = 1 },
            { type = "list_item", text = "Bloodletter’s Bloodletting now procs less frequently.", level = 1 },
            { type = "list_item", text = "Ascendant Serpent health reduced by 10%.", level = 1 },
            { type = "list_item", text = "Rav’i", level = 1 },
            { type = "list_item", text = "Feeding Frenzy no longer increases the rate of Messy Eater and Carrion Burst.", level = 2 },
            { type = "list_item", text = "Fresh Meat piles now display a warning visual when Rav’i is close enough to eat from them.", level = 2 },
            { type = "list_item", text = "Hydrastrike damage reduced by 33%.", level = 2 },
            { type = "list_item", text = "Zul’jan", level = 1 },
            { type = "list_item", text = "The initial cast of Ritual of the Fang now occurs a few seconds later in the encounter.", level = 2 },
            { type = "list_item", text = "Ritual of the Fang cast time increased to 5 seconds (was 4 seconds).", level = 2 },
            { type = "list_item", text = "Fang Empowered damage reduced by 20%.", level = 2 },
            { type = "list_item", text = "The Venomous Abyss", level = 0 },
            { type = "list_item", text = "Vashnik the Malignant", level = 1 },
            { type = "list_item", text = "Reduced target scaling for Adaptive infection to be less punishing for larger group sizes.", level = 2 },
            { type = "list_item", text = "Fixed an issue causing Thinned Blood to be cast on non-mythic difficulties.", level = 2 },
            { type = "list_item", text = "The Lost Explorers", level = 1 },
            { type = "list_item", text = "Resolved an issue causing Final Ascension to inflict less damage than intended.", level = 2 },
            { type = "list_item", text = "Ula’tek", level = 0 },
            { type = "list_item", text = "Adjusted the Caustic Waves from the Gore Rattler so they remain above the floor of the main platform.", level = 1 },
            { type = "list_item", text = "The tooltip for Ula'tek's Volatile Purge no longer contains an error.", level = 1 },
            { type = "h3", text = "Housing" },
            { type = "list_item", text = "Previewing decor in the Decor Catalog will now show accurate Voidlight Marl prices for decor sold by Silvermoon's Disguised Decor Duel Vendor.", level = 0 },
            { type = "h3", text = "Items" },
            { type = "list_item", text = "Hex Lord's Dooming Idol - Hex Lord's Doom stacks are no longer removed upon ending a Mythic+ boss encounter.", level = 0 },
            { type = "h3", text = "Prey" },
            { type = "list_item", text = "Fixed an issue that prevented alts from being able to access the Prey portal between Silvermoon and The Coiled Isle.", level = 0 },
            { type = "hr" },
            { type = "h3", text = "August 20, 2026" },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Havoc", level = 1 },
            { type = "list_item", text = "Aldrachi Reaver: Fixed an issue where Evasive Action was not granting an extra cast of Vengeful Retreat.", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "list_item", text = "Fixed an issue where the tooltip for Tranquility incorrectly described how long it extended heal over time effects.", level = 2 },
            { type = "list_item", text = "Fixed an issue where Overgrowth was applying healing over time effects to the incorrect target when used in tandem with Soul of the Forest.", level = 2 },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Marksmanship", level = 1 },
            { type = "list_item", text = "Corrected an issue where Hunters could benefit from the Precise Shots effect twice by casting Arcane Shot or Multi-Shot as Rapid Fire finishes channeling while talented into Unload.", level = 2 },
            { type = "list_item", text = "Corrected an issue where the AoE damage from Explosive Shot was not properly reduced by damage taken reduction effects.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "list_item", text = "Fixed an issue where casting Benediction and queuing a Holy Word would consume the proc.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Elemental", level = 1 },
            { type = "list_item", text = "Resolved an issue causing Master of the Elements to not increase the damage of Earthquake.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Hellcaller: Fixed an issue where Blackened Soul could trigger from Unstable Affliction periodic damage.", level = 1 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Fixed an issue where Malefic Grasp was not affected by Withering Bolt.", level = 2 },
            { type = "list_item", text = "Fixed an issue where Withering Bolt did not account for Wither when increasing Shadowbolt Volley damage.", level = 2 },
            { type = "list_item", text = "Fixed an issue where Wither would not count toward Darkglare Eye Beam damage increase.", level = 2 },
            { type = "list_item", text = "Fixed an issue where the Unstable Affliction granted by Venomous Abyss 4-piece set bonus would not grant a stack of Wither.", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "Fixed an issue where if Azta'rec killed a player it would display that Zek'vir has burrowed away and did not drop loot.", level = 0 },
            { type = "h3", text = "Dungeons and Raids" },
            { type = "list_item", text = "Ruby Life Pools", level = 0 },
            { type = "list_item", text = "Thunderhead and Flamegullet", level = 1 },
            { type = "list_item", text = "Fixed an issue where certain abilities could cause their breath spells to cancel unexpectedly.", level = 2 },
            { type = "list_item", text = "Temple of Sethraliss", level = 0 },
            { type = "list_item", text = "Avatar of Sethraliss", level = 1 },
            { type = "list_item", text = "Fixed an issue where the progress bar could reach 100% when the Avatar reached 99% health.", level = 2 },
            { type = "list_item", text = "The Venomous Abyss", level = 0 },
            { type = "list_item", text = "Resolved an issue where players could fall through the world in The Serpent Warren.", level = 1 },
            { type = "list_item", text = "Vashnik the Malignant", level = 1 },
            { type = "list_item", text = "Fixed an issue causing Stygian Burst to inflict damage in a larger area than intended.", level = 2 },
            { type = "list_item", text = "Shrouded Venom health redistributed and now have 40% health and 60% shields.", level = 2 },
            { type = "list_item", text = "Fixed an issue causing players to get hit multiple times from the same wave in a short period of time.", level = 2 },
            { type = "list_item", text = "Fixed a rare issue where players using Harpoon on a Venom while inside the Malignant Cavity would cause them to fall through the playspace.", level = 2 },
            { type = "list_item", text = "The Coiled Altar", level = 1 },
            { type = "list_item", text = "Fixed an issue where the encounter would rarely fail to properly transition to Phase 3 at the end of the intermission.", level = 2 },
            { type = "list_item", text = "Ula’tek", level = 1 },
            { type = "list_item", text = "Blight Vein damage reduced on Heroic difficulty.", level = 2 },
            { type = "list_item", text = "Grasping Fangs now targets three players per side on Heroic difficulty, no matter the instance group size.", level = 2 },
            { type = "list_item", text = "Volatile Purge's area of effect now scales with raid size in Normal and Heroic difficulties. The effect radius is largest in a 10-player raid and gradually decreases as raid size increases, reaching its smallest size in a 30-player raid.", level = 2 },
            { type = "list_item", text = "Resolved an issue causing the damage of Spectral Coils to unintentionally scale on non-Mythic difficulties.", level = 2 },
            { type = "list_item", text = "Spectral Coils now requires 40% of the raid to reduce its damage to a minimum value.", level = 2 },
            { type = "list_item", text = "Spectral Coils adjusted on Heroic difficulty so it has more consistent timing.", level = 2 },
            { type = "list_item", text = "Corrected an issue where the Blight Vein debuff did not properly inflict its damage based on the number of stacks applied, on Heroic and Mythic difficulties.", level = 2 },
            { type = "list_item", text = "Corrected an issue where Hunters’ Stampede pets from the Pack Leader hero talents would not properly damage the Heart of Ula'tek during the encounter.", level = 2 },
            { type = "h3", text = "Items" },
            { type = "list_item", text = "Companion Command Crystal is now bind-on-pickup.", level = 0 },
            { type = "h3", text = "Omnium Folio" },
            { type = "list_item", text = "Fixed an issue with a previous change to the Omnium Folio's Rune of Unleashed Fire that resulted in pulling enemies you were not in combat with.", level = 0 },
            { type = "h3", text = "Prey" },
