            { type = "list_item", text = "Hunting Leap visibility of ground visual improved.", level = 2 },
            { type = "list_item", text = "Den of Nalorakk", level = 0 },
            { type = "list_item", text = "Barrel of Apples are now interactable without requiring opposable thumbs. Nature finds a way.", level = 1 },
            { type = "list_item", text = "Warding Incense", level = 1 },
            { type = "list_item", text = "Increased Versatility buff to 5% (was 3%).", level = 2 },
