            { type = "list_item", text = "The Council of Tribes", level = 1 },
            { type = "list_item", text = "Encounter now ends immediately after defeating Zanazal the Wise.", level = 1 },
            { type = "list_item", text = "Dazar, The First King", level = 1 },
            { type = "list_item", text = "Impaling Spear ground visual updated to improve visibility.", level = 2 },
            { type = "list_item", text = "Shadow of Zul", level = 1 },
