            { type = "list_item", text = "Reduced required enemy forces to 655 (was 690).", level = 1 },
            { type = "list_item", text = "Removed the creature pack of a Corrupted Warlock and two Wrathguard Flayers before Xathuux the Annihilator.", level = 1 },
            { type = "list_item", text = "Cantina event", level = 1 },
            { type = "list_item", text = "Five Star Review duration increased to 5 minutes (was 4 minutes).", level = 2 },
            { type = "list_item", text = "Food Missiles now targets specific locations around the room.", level = 2 },
            { type = "list_item", text = "Felmaster Lucsei", level = 1 },
            { type = "list_item", text = "Blade Dance now has a 2-second cast time, and impact damage reduced by 10%.", level = 2 },
            { type = "list_item", text = "Ruby Life Pools", level = 0 },
            { type = "list_item", text = "Melidrussa Chillworn", level = 1 },
            { type = "list_item", text = "Hailburst cast time increased to 3 seconds (was 2 seconds).", level = 2 },
            { type = "list_item", text = "Kyrakka and Erkhart Stormvein", level = 1 },
            { type = "list_item", text = "Flaming Embers", level = 2 },
            { type = "list_item", text = "Reduced radius of each ember to 5 yards (was 7 yards).", level = 3 },
            { type = "list_item", text = "Reduced amount of randomness in the spawn pattern.", level = 3 },
            { type = "list_item", text = "Kyrakka no longer immediately begins casting after she lands for the final phase of the encounter, allowing for her to be repositioned", level = 2 },
            { type = "list_item", text = "Increased the movement speed of Kyrakka after she lands for the final phase of the encounter", level = 2 },
            { type = "list_item", text = "Addressed an issue where Kyrakka could melee attack unexpected targets after landing for the final phase", level = 2 },
            { type = "list_item", text = "Flashfrost Chillweaver", level = 1 },
            { type = "list_item", text = "Ice Shield precast visual visibility improved.", level = 2 },
            { type = "list_item", text = "Earthbound Guardian", level = 1 },
            { type = "list_item", text = "Multiple applications of the Earthbound’s Imprint debuff can no longer overlap.", level = 2 },
            { type = "list_item", text = "Temple of Sethraliss", level = 0 },
            { type = "list_item", text = "Avatar of Sethraliss", level = 1 },
            { type = "dev_note", text = "With the changes below, we’re reducing the amount of passive healing done to the boss via Cleansed Lifeforce to make player healing more impactful. Additionally, we are adjusting some mechanical tuning surrounding Corrupted Lifeforce to encourage more group participation in this mechanic. To counterbalance this adjustment, we’re providing more time for the group to handle this mechanic and also increasing its visibility within the Avatar’s chamber.", level = 2 },
            { type = "list_item", text = "Corrupted Guardian", level = 2 },
            { type = "list_item", text = "Corrupted Lifeforce time to soak increased to 6 seconds (was 4.5 seconds) and visibility improved.", level = 3 },
            { type = "list_item", text = "Corruption", level = 2 },
            { type = "list_item", text = "Reduced physical vulnerability to 250% (was 300%).", level = 3 },
            { type = "list_item", text = "Increased periodic damage by 33%.", level = 3 },
            { type = "list_item", text = "Tainted Strike", level = 2 },
            { type = "list_item", text = "Reduced periodic damage by 50%.", level = 3 },
            { type = "list_item", text = "Capped applications at 2.", level = 3 },
            { type = "list_item", text = "Increased duration to 25 seconds.", level = 3 },
            { type = "list_item", text = "Cleansed Lifeforce", level = 2 },
            { type = "list_item", text = "The passive healing aura can no longer grow beyond 3 applications.", level = 3 },
            { type = "list_item", text = "Slowed the tick rate of the passive healing to every 3 seconds (was every 2 seconds).", level = 3 },
            { type = "list_item", text = "Faithless Tormentor", level = 2 },
            { type = "list_item", text = "Reduced the size of the fixate visual over the head of the healer.", level = 3 },
            { type = "list_item", text = "Fixed an issue where Faithless Tormentors could melee their fixate target from further than intended.", level = 3 },
            { type = "list_item", text = "Essence Defiler", level = 2 },
            { type = "list_item", text = "Defiling Taint is now displayed as a debuff on the Avatar’s unit frame.", level = 3 },
            { type = "list_item", text = "Lightning Serpent", level = 2 },
            { type = "list_item", text = "Multiple applications of the Lingering Storm debuff can no longer overlap.", level = 3 },
            { type = "list_item", text = "Voidscar Arena", level = 0 },
            { type = "list_item", text = "Proof of Mastery and Proof of Endurance are now buffs.", level = 1 },
            { type = "list_item", text = "Aegyra the Unyielding", level = 1 },
            { type = "list_item", text = "Champion’s Spear health reduced by 15%.", level = 2 },
            { type = "list_item", text = "Raj’kess the Spellstorm", level = 1 },
            { type = "list_item", text = "Disruption Orb disruption cast time reduced to 13 seconds (was 15 seconds).", level = 2 },
            { type = "h3", text = "Items" },
            { type = "list_item", text = "Fixed an issue with Hunter's Ritual Stone providing more stats than intended.", level = 0 },
            { type = "list_item", text = "Shirts collected from Free T-Shirt Day can now be sold to vendors.", level = 0 },
            { type = "list_item", text = "Zatha'tek, Breath of Corruption may now be equipped in either weapon slot.", level = 0 },
            { type = "list_item", text = "Aman'muso, Warlord's Vengeance may now be equipped in either weapon slot.", level = 0 },
            { type = "list_item", text = "Preternatural Antivenom - fixed an issue preventing the healing effect from consistently triggering after the aura has been applied to an ally depending on the source of incoming damage.", level = 0 },
            { type = "list_item", text = "Preyhunter's Trophy Stand cannot be used in areas where toys are restricted", level = 0 },
            { type = "h3", text = "Player versus Player" },
            { type = "list_item", text = "Training Grounds: Arenas", level = 0 },
            { type = "list_item", text = "The damage of enemy game-controlled opponents has been reduced in Training Grounds: Arena.", level = 1 },
            { type = "list_item", text = "Resolved an issue that prevented “Week 1 of 3: Gladiator's Distinction” quest credit from being earned in Training Grounds: Arenas.", level = 1 },
            { type = "list_item", text = "Resolved an issue that could prevent quest credit for “Sparks of War: The Coiled Isle”.", level = 0 },
            { type = "list_item", text = "The PvP trinket set bonus now increases primary stat by 20% for damage dealers and tanks (was 15%).", level = 0 },
            { type = "dev_note", text = "We’ve felt the pace of PvP combat has been slower than intended, so we’re increasing the primary stat of non-healer specializations to increase overall outgoing damage.", level = 1 },
            { type = "list_item", text = "Demon Hunter", level = 0 },
            { type = "list_item", text = "Devourer", level = 1 },
            { type = "dev_note", text = "Devourer Demon Hunters are both very threatening and very defensible during Void Metamorphosis and Surrender to the Void has provided the opportunity to increase the duration of those windows too significantly, so its Fury generation effect is being reduced.", level = 2 },
            { type = "list_item", text = "Surrender to the Void now increases Fury generated by 60% (was 100%).", level = 2 },
            { type = "list_item", text = "Druid", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "Restoration Druid received several changes in Curse of Ula’tek that improved its throughput beyond what we would like in PvP.", level = 2 },
            { type = "list_item", text = "All healing reduced by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Mage", level = 0 },
            { type = "list_item", text = "Fire", level = 1 },
            { type = "dev_note", text = "Fire Mage’s Venomous Abyss tier set bonus is particularly difficult to take advantage of in PvP combat, so we’re making a few tweaks with the objective of increasing its usability. We’re also decreasing Meteor’s damage to reduce Fire Mage’s burst capabilities.", level = 2 },
            { type = "list_item", text = "Pyroblast damage increased by 10% in PvP combat.", level = 2 },
            { type = "list_item", text = "Meteor damage decreased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Comet Storm damage decreased by 20% in PvP combat.", level = 2 },
            { type = "list_item", text = "Venomous Abyss 4-piece set bonus updated – Now decreases the cast time of Pyroblast and Flamestrike by 30% (was 10%) and increases Pyroclasm’s damage bonus by 5% (was 10%) in PvP combat.", level = 2 },
            { type = "list_item", text = "Paladin", level = 0 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "dev_note", text = "Holy Paladin’s throughput has been higher than we would like, and Judgment has been too effective as an offensive tool. Avenging Crusader’s effectiveness is being increased to offset the decrease to Judgment’s damage.", level = 2 },
            { type = "list_item", text = "All healing decreased by 5% in PvP combat.", level = 2 },
            { type = "list_item", text = "Judgment damage decreased by 30% in PvP combat.", level = 2 },
            { type = "list_item", text = "Avenging Crusader now transfers 80% of damage done into healing in PvP combat (was 55%).", level = 2 },
            { type = "list_item", text = "Retribution", level = 1 },
            { type = "dev_note", text = "Retribution had been contributing to longer PvP matches during Season 1 due to their frequent access to team utility. We’re shifting some of that effectiveness into more consistent offensive power, and additionally giving Templar an increase to Hammer of Light damage so they are a solid offensive alternative to Herald of the Sun.", level = 2 },
            { type = "list_item", text = "All damage increased by 8% in PvP combat.", level = 2 },
            { type = "list_item", text = "Final Verdict damage increased by 15% in PvP combat.", level = 2 },
            { type = "list_item", text = "Hammer of Light damage increased by 25% in PvP combat.", level = 2 },
            { type = "list_item", text = "Sacrifice of the Just now reduces Blessing of Sacrifice’s cooldown by 30 seconds in PvP combat (was 60 seconds).", level = 2 },
            { type = "list_item", text = "Unbreakable Spirit reduces the cooldown of affected spells by 20% in PvP combat (was 30%).", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Restoration", level = 1 },
            { type = "dev_note", text = "We’re making some targeted adjustments to primarily improve Farseer’s viability as we begin season 2. We’re also reducing the effectiveness of Storm Conduit which we feel has been too powerful under the right circumstances.", level = 2 },
            { type = "list_item", text = "All healing increased by 4% in PvP combat.", level = 2 },
            { type = "list_item", text = "Storm Conduit now reduces the cooldown of affected spells by 2 seconds (was 4 seconds).", level = 2 },
            { type = "list_item", text = "Storm Conduit now reduces the duration of interrupts on Lightning Bolt and Chain Lightning by 40% (was 65%).", level = 2 },
            { type = "list_item", text = "Farseer: Healing Wave, Healing Surge, and Chain Heal healing from Ancestors increased by 35% in PvP combat.", level = 2 },
            { type = "list_item", text = "Farseer: Hydrobubble absorption increased by 35% in PvP combat.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Soul Fire damage reduced by 30% in PvP combat.", level = 2 },
            { type = "h3", text = "Professions" },
            { type = "list_item", text = "Fixed an issue where players were not receiving Tidal Spark Dust from quests such as “Trailing Xal'atath” and “Midnight: World Tour”.", level = 0 },
            { type = "list_item", text = "Raised the base cap of Tidal Spark Dust to 3 (was 1).", level = 0 },
            { type = "list_item", text = "Cooking", level = 0 },
            { type = "list_item", text = "Fixed a bug where the tooltips for Hearty Loa's Gathering, Hearty Amani Cornucopia, and Hearty Feast of Knowledge listed incorrect stat values.", level = 1 },
            { type = "h3", text = "Quests" },
            { type = "list_item", text = "“Trailing Xal'atath” and “Midnight: World Tour” should now correctly award Tidal Spark Dust.", level = 0 },
            { type = "list_item", text = "Fixed bug preventing the “Sparks of War” related quests from displaying Spark of Tides as a potential quest reward.", level = 0 },
            { type = "list_item", text = "Fixed an issue that would prevent \"Purging the Vaults\" or \"Vaults of Atal'Utek: A Toxic Tour\" quests from being completed if you already had Codex of the Soulcoilers in your inventory.", level = 0 },
            { type = "list_item", text = "For “A Grave Concern”, the Budget Friendly gravestone in the Silvermoon Delve hub is now available for anyone to use.", level = 0 },
            { type = "hr" },
            { type = "h3", text = "August 17, 2026" },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Hunter", level = 0 },
            { type = "list_item", text = "Beast Mastery", level = 1 },
            { type = "list_item", text = "Corrected an issue where Dire Beast Kill Commands from the Wildspeaker Talent did not properly benefit from Killer Instinct, Alpha Predator, Specialized Arsenal, or Savagery.", level = 2 },
            { type = "list_item", text = "Priest", level = 0 },
            { type = "list_item", text = "Holy", level = 1 },
            { type = "list_item", text = "Corrected an issue where swapping from Shadow to Holy specializations could improperly cause Shadow Word: Pain to not turn into Holy Fire.", level = 2 },
            { type = "list_item", text = "Shaman", level = 0 },
            { type = "list_item", text = "Corrected an issue where swapping between specs may incorrectly cause Lava Burst to show up as Primal Strike in your spellbook.", level = 1 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Destruction", level = 1 },
            { type = "list_item", text = "Fixed an issue where the tooltip of Shadowburn would not display the correct duration.", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "In Delves, Ula'tek's Amphisbaena Writhing Strike poison can only get one aura at a time. Damage reduced 25%, and the cooldown on Writhing Strike increased.", level = 0 },
            { type = "list_item", text = "Fixed an issue causing Corrosive Bilespear to not proc at higher ranks.", level = 0 },
            { type = "h3", text = "Lairs" },
            { type = "list_item", text = "Resolved an issue causing the sharks to not bite in The Tidebound Grotto.", level = 0 },
            { type = "h3", text = "Naigtal and Val" },
            { type = "list_item", text = "Players in Heroic World Tier can again talk with a sprit healer to exit Heroic World Tier and resurrect.", level = 0 },
            { type = "h3", text = "Quests" },
            { type = "list_item", text = "Ofi the Sly should now properly accept that the concoction is complete for \"Acceptable Apprentice\".", level = 0 },
            { type = "list_item", text = "Fixed an issue preventing characters under level 90 from completing activities related to Saltheril's Soiree and Abundance.", level = 0 },
            { type = "hr" },
            { type = "h3", text = "August 14, 2026" },
            { type = "h3", text = "Achievements" },
            { type = "list_item", text = "Reaching Renown 20 with Zul'jaara's Forces now correctly grants Zul'jarra's Forces Champion .", level = 0 },
            { type = "list_item", text = "Family Battler of Outland and all associated type- Battler of Outland achievements now require Bloodknight Antairi (was incorrectly Gorma Asaan).", level = 0 },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Evoker", level = 0 },
            { type = "list_item", text = "Devastation", level = 1 },
            { type = "list_item", text = "Shattering Star now correctly benefits from Mastery: Giantkiller.", level = 2 },
            { type = "list_item", text = "Warrior", level = 0 },
            { type = "list_item", text = "Arms, Fury", level = 1 },
            { type = "list_item", text = "Slayer: Fixed a bug that was causing Executioner to have double the intended effect.", level = 2 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Fixed an issue where Warlock pets would continually learn Soul Leech.", level = 1 },
            { type = "list_item", text = "Demonology", level = 1 },
            { type = "list_item", text = "Soul Harvester: fixed an issue where Shadow Bolt and Hand of Gul'dan would be disabled in the cooldown manager.", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "Fixed an issue where Gorgoneion Gaze would not trigger.", level = 0 },
            { type = "list_item", text = "Fixed an issue where Ula'tek's Gift would not deal damage.", level = 0 },
            { type = "list_item", text = "Fixed an issue where Ula'tek's Gift would not apply more stacks while poisoned.", level = 0 },
            { type = "h3", text = "Dungeons and Raids" },
            { type = "list_item", text = "Archmage Timear again permits players to queue for the Raid Finder wings of Tomb of Sargeras.", level = 0 },
            { type = "list_item", text = "Ruby Life Pools", level = 0 },
            { type = "list_item", text = "Thunderhead", level = 1 },
            { type = "list_item", text = "Fixed an issue where Electrical Discharge would sometimes fail to hit players.", level = 2 },
            { type = "list_item", text = "Voidscar Arena", level = 0 },
            { type = "list_item", text = "Addressed an issue where Brutok's Smashing Charge can charge through doors.", level = 1 },
            { type = "h3", text = "Items" },
            { type = "list_item", text = "Void-Twisted Sporbits no longer grant Nebulous Voidcores. Nebulous Voidcores obtained in this way after the end of Season 1 have been removed for Season 2.", level = 0 },
            { type = "list_item", text = "Tanks may now roll Need on Zul'jin's Guillotine Technique.", level = 0 },
            { type = "list_item", text = "Survival Hunters may now roll Need on two-handed axes and swords with Agility.", level = 0 },
            { type = "list_item", text = "Trinkets", level = 0 },
            { type = "list_item", text = "Coiled Fangstone: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Crucible of Erratic Energies: critical strike reduced by 15%.", level = 1 },
            { type = "list_item", text = "Fang of Umbral Malignance: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "First Mate's Shellward: damage increased by 25%.", level = 1 },
            { type = "list_item", text = "Font of Venomous Rage: damage increased by 20%.", level = 1 },
            { type = "list_item", text = "Gaze of the Alnseer: primary stat reduced by 20%.", level = 1 },
            { type = "list_item", text = "Gebbo's Bottomless Bag: secondary stat effects reduced by 29%.", level = 1 },
            { type = "list_item", text = "Hex Lord's Dooming Idol: intellect lost per stack reduced by 33% and intellect granted on use per stack increased by 15%.", level = 1 },
            { type = "list_item", text = "Idol of the Howling Nexus: agility and strength on proc increased by 5%.", level = 1 },
            { type = "list_item", text = "Knot of Writhing Serpents: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Knot of Writhing Serpents no longer drops for healing specializations.", level = 1 },
            { type = "list_item", text = "Kyrakka's Searing Embers: healing increased by 80% and damage increased by 50%.", level = 1 },
            { type = "list_item", text = "Mindpiercer's Sigil: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Mycolic Medicine: all healing increased by 30%.", level = 1 },
            { type = "list_item", text = "Preternatural Antivenom: healing increased by 30% and fixed an issue preventing the healing effect from consistently triggering after the aura has been applied to an ally depending on the source of incoming damage.", level = 1 },
            { type = "list_item", text = "Sapling of the Dawnroot: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Soulcoiler Ritual Vessel: absorb reduced by 15%.", level = 1 },
            { type = "list_item", text = "Sszorak's Ferocity: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Tiny Electromental in a Jar: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Tumor of the Swarm: damage increased by 15% and healing increased by 40%.", level = 1 },
            { type = "list_item", text = "Unstable Felheart Crystal: absorb increased by 30%.", level = 1 },
            { type = "list_item", text = "Vaelgor's Final Stare: mastery reduced by 10%.", level = 1 },
            { type = "list_item", text = "Vashnik's Sanguine Rancor: damage increased by 15%.", level = 1 },
            { type = "list_item", text = "Vexhul's Everflowing Gland: damage increased by 15%.", level = 1 },
            { type = "h3", text = "Lairs" },
            { type = "list_item", text = "Resolved an issue causing some Bubblefin Shorerunners to not despawn when reaching the Alluring Bubble.", level = 0 },
            { type = "h3", text = "Player versus Player" },
            { type = "list_item", text = "Fixed an issue where Ula'tek's Gift was dealing more damage to players than expected.", level = 0 },
            { type = "h3", text = "Professions" },
            { type = "list_item", text = "Fixed an issue that prevented Flat Snakeskin Canopy from being crafted.", level = 0 },
            { type = "list_item", text = "Fixed an issue that prevented Flat Snakeskin Canopy from being added to the decor collection when used.", level = 0 },
            { type = "h3", text = "Quests" },
            { type = "list_item", text = "Fixed a bug causing Amani Endeavor daily quests to only be offered weekly.", level = 0 },
            { type = "list_item", text = "Players on the quest “Void Walk With Me” are now correctly advanced in the “Traitor's Due” story when entering The Shadow Enclave.", level = 0 },
            { type = "list_item", text = "“Story of a Memorable Victory” no longer drops outside of the Dragon Isles.", level = 0 },
            { type = "list_item", text = "Fixed an issue preventing progress on the quest “Cut Her Strings” in Voidstorm.", level = 0 },
            { type = "list_item", text = "“Awe of She” is no longer stalled by weather effects on the player.", level = 0 },
            { type = "list_item", text = "Fixed a bug preventing players who are seated before entering the Worldsoul Terror as Nek'zali from properly interacting with Injured Hunters on “Fuel the Calling”.", level = 0 },
            { type = "h3", text = "Trading Post" },
            { type = "list_item", text = "The Trading Post activity \"Complete 'A Call for Aid' Storyline\" should now require only quests within that storyline.", level = 0 },
            { type = "hr" },
            { type = "h3", text = "August 13, 2026" },
            { type = "h3", text = "Classes" },
            { type = "list_item", text = "Spirit Walk in the Vaults of Atal'utek should now apply to pets.", level = 0 },
            { type = "list_item", text = "Warlock", level = 0 },
            { type = "list_item", text = "Affliction", level = 1 },
            { type = "list_item", text = "Fixed an issue where Seed of Corruption would not consume Shard Instability on cast.", level = 2 },
            { type = "h3", text = "Delves" },
            { type = "list_item", text = "Fixed an issue where the Delve Shadowguard Point: Shadowguard Survivor would not grant Great Vault credit upon completion.", level = 0 },
            { type = "list_item", text = "Fixed a bug causing Ritual Sites to appear to grant Great Vault rewards that were inconsistent with the available Tiers. Next week, the Great Vault will reward the intended tiers 1-6 for week 1 activities.", level = 0 },
            { type = "list_item", text = "Fixed an issue with the Corrosive Codex that caused Corrosive Powers unlocked on one character to not show up as available options in the Corrosive Codex for other characters.", level = 0 },
            { type = "h3", text = "Dungeons" },
            { type = "list_item", text = "Players who have not yet completed precursor campaign quests should now be able to be summoned to the Vaults of Atal’Utek by Altar of Fangs dungeon groups.", level = 0 },
            { type = "list_item", text = "Altar of Fangs", level = 0 },
            { type = "list_item", text = "Addressed an issue where Uncoiled Writhe constantly switches target with Spiteful Hunt.", level = 1 },
            { type = "list_item", text = "Addressed an issue where interacting with Infusion Totem may fail to trigger the event.", level = 1 },
            { type = "list_item", text = "Voidscar Arena", level = 0 },
            { type = "list_item", text = "Addressed an issue where defeating Aegyra the Unyielding while she's channeling Earthsplitter can fail to open the door to the arena.", level = 1 },
            { type = "h3", text = "Items" },
            { type = "list_item", text = "Fixed an issue that caused Venomjade Necklace to sometimes be invisible.", level = 0 },
            { type = "h3", text = "Lairs" },
            { type = "list_item", text = "Players cannot receive loot from Nymrissa Wavecaller more than once per week in World difficulty.", level = 0 },
            { type = "h3", text = "Player versus Player" },
            { type = "list_item", text = "Gorgoneion Gaze no longer petrifies players indefinitely.", level = 0 },
            { type = "list_item", text = "Fixed a bug preventing Otherworldly Sparks of War from dropping in Naigtal and Val activities. The Naigtal and Val Sparks of War quests will no longer be offered when Season 2 begins.", level = 0 },
            { type = "h3", text = "Professions" },
            { type = "list_item", text = "[With realm restarts] Jewelcrafting and Tailoring Profession Knowledge books from the forces of Zul'jarra should now correctly award profession Knowledge. Players who got the books prior to this fix should be given the Knowledge retroactively.", level = 0 },
            { type = "list_item", text = "Fixed an issue that caused Contract: Zul'jarra's Forces to sometimes incorrectly apply Amani Tribe Contract when used.", level = 0 },
            { type = "h3", text = "Quests" },
            { type = "list_item", text = "Fixed an issue where players could begin Curse of Ula'tek campaign quests without first completing the main Midnight campaign.", level = 0 },
            { type = "dev_note", text = "The Curse of Ula'tek campaign was intended to require account completion of the main Midnight campaign before it could be started, as completing these features out of order could result in players being in a misleading or confusing state. Players who have not yet started the Curse of Ula’tek campaign must now complete the main Midnight campaign on one character per account. Any player-characters who have already started the Curse of Ula'tek campaign should be unaffected and can continue it and complete it.", level = 1 },
            { type = "list_item", text = "Players who completed \"Legends of the Haranir\" quests split among multiple characters will now be able to resume \"The Empty Cradle\" questline.", level = 0 },
            { type = "list_item", text = "“Cold As Ice” no longer sends players on a cold canoe ride into the abyss.", level = 0 },
            { type = "list_item", text = "Removed an incorrect map marker for “A Suspicious Stew”.", level = 0 },
            { type = "list_item", text = "Bob has been found and returned to his bartending.", level = 0 },
            { type = "h3", text = "World" },
            { type = "list_item", text = "Fixed a bug that could cause players to disconnect when entering the Lunarfall Garrison Excavation area.", level = 0 },
            },
        },
        ["2026-08-18-item-adjustment-incoming-august-25-77063a3f31"] = {
            id = "2026-08-18-item-adjustment-incoming-august-25-77063a3f31",
            post_key = "77063a3f31",
            title = "Item Adjustment Incoming - August 25",
            category = "General Discussion (US)",
            timestamp = 1787089522,
            url = "https://us.forums.blizzard.com/en/wow/t/2338382/1",
            content = {
            { type = "p", text = "With a hotfix that will go live with scheduled weekly maintenance on August 25, we’re adjusting one item:" },
            { type = "h2", text = "ITEMS" },
            { type = "list_item", text = "Aqirbane Reliquary now grants a smaller quantity of all secondary stats (was a large quantity of only Critical Strike). Its first on-equip effect is unchanged, and its second on-equip effect has been updated to increase a random secondary stat (was only Critical Strike) while decreasing the other three.", level = 0 },
            },
        },
        ["2026-08-18-item-adjustment-incoming-26-august-85ebfaaaf9"] = {
            id = "2026-08-18-item-adjustment-incoming-26-august-85ebfaaaf9",
            post_key = "85ebfaaaf9",
            title = "Item Adjustment Incoming - 26 August",
            category = "General Discussion (EU)",
            timestamp = 1787089514,
            url = "https://eu.forums.blizzard.com/en/wow/t/626209/1",
            content = {
            { type = "p", text = "With a hotfix that will go live with scheduled weekly maintenance on August 26, we’re adjusting one item:" },
            { type = "h2", text = "ITEMS" },
            { type = "list_item", text = "Aqirbane Reliquary now grants a smaller quantity of all secondary stats (was a large quantity of only Critical Strike). Its first on-equip effect is unchanged, and its second on-equip effect has been updated to increase a random secondary stat (was only Critical Strike) while decreasing the other three.", level = 0 },
            },
        },
        ["2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7"] = {
            id = "2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7",
            post_key = "7a43ed4dc7",
            title = "Curse of Ula’tek: The Venomous Abyss Raid Now Live!",
            category = "Blogs (US)",
            timestamp = 1787076009,
            url = "https://news.blizzard.com/en-us/article/24294062/curse-of-ulatek-the-venomous-abyss-raid-now-live",
            content = {
            { type = "p", text = "Within the depths of the Venomous Abyss, Ula’tek stirs once more. Awakened by Zul’jan’s actions, this ancient force of hatred, corruption, and venom threatens to unleash her brood from the heart of an eight-boss raid dungeon. Gather your allies, carve a path through the vaults, and prepare to face Ula’tek in her inner sanctum." },
            { type = "hr" },
            { type = "h3", text = "Raid Details:" },
            { type = "list_item", text = "Where: The Coiled Isle", level = 0 },
            { type = "list_item", text = "Raid Bosses: 8", level = 0 },
            { type = "list_item", text = "Level: 90", level = 0 },
            { type = "list_item", text = "Difficulties: Raid Finder, Normal, Heroic, Mythic, Story Mode", level = 0 },
            { type = "list_item", text = "Raid Finder Minimum Item Level: 273", level = 0 },
            { type = "p", text = "Raid Unlock Schedule:" },
            { type = "p", text = "All unlocks are with each region’s weekly maintenance reset, unless otherwise noted." },
            { type = "list_item", text = "Week of August 18: Normal, Heroic, Mythic Difficulty, Raid Finder Wing 1- The Soulcoilers (Nek’zali the Soulcoiler; The Twin Fangs)", level = 0 },
            { type = "list_item", text = "Week of August 25: Story Mode, Raid Finder Wing 2- The Essence of Venom (Entombed Sentinels; Vashnik the Malignant)", level = 0 },
            { type = "list_item", text = "Week of September 1: Raid Finder Wing 3- The Serpent Warren (The Lost Explorers; Sszorak)", level = 0 },
            { type = "list_item", text = "Week of September 8: Raid Finder Wing 4- The Tomb of Ula’tek- (The Coiled Altar; Ula’tek)", level = 0 },
            { type = "hr" },
            { type = "h3", text = "The Venomous Abyss" },
            { type = "image", width = 720, height = 277, u = 0.703125, v = 0.541016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-1.jpg" },
            { type = "p", text = "Guided by the dark whispers of Malacrass, Zul’jan has freed the forgotten broods of Ula’tek from their prison. As the monster’s power grows, Zul’jarra calls upon the Champions of Azeroth to descend into the Vaults of Atal’Utek to stop her brother before the weapon is unleashed upon Azeroth." },
            { type = "h2", text = "BOSSES" },
            { type = "h3", text = "The Soulcoil Well" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-2.jpg" },
            { type = "p", text = "Nek’zali the Soulcoiler" },
            { type = "p", text = "Long ago, the shadow hunter Nek’zali and her followers were entombed for the blasphemous act of summoning Ula’tek. Restored by the very power she unleashed, she calls the other Soulcoilers from their tombs to serve her once more." },
            { type = "h3", text = "The Vile Crypt" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-3.jpg" },
            { type = "p", text = "Entombed Sentinels" },
            { type = "p", text = "The Blood and Breath of Ula’tek bar the way to Vashnik’s inner sanctum. Ancient golems that long stood guard within the vaults, now corrupted by the venom of the nightmarish monster they imprisoned." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-4.jpg" },
            { type = "p", text = "Vashnik the Malignant" },
            { type = "p", text = "Within the Chamber of Virulence, Vashnik the Malignant distills Ula’tek’s venoms into ever more lethal forms. The creature lurks in its noxious chamber, brewing foul toxins to empower its brood." },
            { type = "h3", text = "Crypt of the Soulcoilers" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-5.jpg" },
            { type = "p", text = "The Lost Explorers" },
            { type = "p", text = "A band of tortollan, possessed by spirits, have come to their senses near the sarcophagus of an ancient Soulcoiler. Trapped in the vault, they seek ancient artifacts to protect themselves from further possession by vengeful spirits." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-6.jpg" },
            { type = "p", text = "Sszorak" },
            { type = "p", text = "A horrifying creature, warped by Ula’tek’s toxic venom, Sszorak is a brutal instrument of vengeance. Calling upon the winds that howl deep within Atal’Utek, it tears apart any living creature it encounters." },
            { type = "h3", text = "Pit of Fangs" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-7.jpg" },
            { type = "p", text = "The Twin Fangs" },
            { type = "p", text = "The first of Ula’tek’s blood, Vexhul and Ithraz brood beneath a roiling sea of venom deep within the vault of Atal’Utek. Any foolish enough to enter the prison’s inner chamber risk their monstrous jaws and toxic strikes." },
            { type = "h3", text = "The Coiled Altar" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-8.jpg" },
            { type = "p", text = "The Coiled Altar" },
            { type = "p", text = "The spirit of Malacrass will not release his grip on Zul’jan so easily. At the Coiled Altar, the shaman commands the warrior to enact the final ritual to unleash Ula’tek on the Amani—for revenge, and to gain their promised reward." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-9.jpg" },
            { type = "p", text = "Ula’tek" },
            { type = "p", text = "The great shame of the Amani empire. The vast complex of Atal’Utek was created to imprison the weapon that proved to be as much of a threat as the enemy she was intended to destroy. Ula’tek has risen from her ancient slumber and threatens all of Azeroth if she should escape." },
            { type = "p", text = "Learn more about each boss, their complete list of loot, and their abilities in the Adventure Journal (Shift-J)." },
            { type = "hr" },
            { type = "h3", text = "Achievements" },
            { type = "h2", text = "ALL DIFFICULTIES" },
            { type = "list_item", text = "The Venomous Abyss: Essence of Ula’tek - Defeat the following bosses within The Venomous Abyss: Nek’zali the Soulcoiler; Entombed Sentinels; Vashnik the Malignant", level = 0 },
            { type = "list_item", text = "The Venomous Abyss: Beasts of Ula’tek - Defeat the following bosses within The Venomous Abyss: The Lost Explorers; Sszorak, The Twin Fangs.", level = 0 },
            { type = "list_item", text = "The Venomous Abyss: Ula’tek - Defeat the following bosses within The Venomous Abyss: The Coiled Altar, Ula’tek.", level = 0 },
            { type = "list_item", text = "The Venomous Abyss: - Defeat the following bosses on any difficulty: Nek’zali the Soulcoiler, Entombed Sentinels, The Lost Explorers, Vashnik the Malignant, Ssorak, The Twin Fangs, The Coiled Altar, Ula’tek.", level = 0 },
            { type = "h2", text = "NORMAL DIFFICULTY AND HIGHER" },
            { type = "list_item", text = "• Well, Well, Little Sky : Defeat Nek’zali, the Soulcoiler after returning Kupamanduka to the Soulcoil Well in The Venomous Abyss on Normal difficulty or higher.", level = 0 },
            { type = "list_item", text = "• Is Venom Stasis A Joke To You? - Defeat the Entombed Sentinels after each Sentinel uses Vitriolic Stasis to restore more than half its total health in The Venomous Abyss on Normal difficulty or higher. -Breath of Ula’tek healed -Blood of Ula’tek healed", level = 0 },
            { type = "list_item", text = "Accidental Inclusion - Defeat The Lost Explorers including Hoji in The Venomous Abyss on Normal difficulty or higher. -Include Hoji in the fight", level = 0 },
            { type = "list_item", text = "Kept You Waiting Huh? - Defeat Vashnik after killing the Solidified Snake Venom in The Venomous Abyss on Normal difficulty or higher. -Slay the Solidified Snake Venom", level = 0 },
            { type = "list_item", text = "Jumping Through Hoops - Defeat Sszorak while jumping through each ring that appears in The Venomous Abyss on Normal difficulty or higher. – All rings jumped through", level = 0 },
            { type = "list_item", text = "Taking a Bite out of Slime - Defeat the Twin Fangs after feeding Ithraz the following slimes in order during Ravenous feast in The Venomous Abyss on Normal difficulty or higher. – Crunchy Appetizer fed – Sumptuous Soup Fed – Tasty Blob Fed – Jiggly dessert fed", level = 0 },
            { type = "list_item", text = "Watch Out Behind You - Defeat the Coiled Altar while all players are fflicted by Unnerving Fication in The Venomous Abyss on Normal difficulty or higher. – All players afflicted with Unnerving fixation", level = 0 },
            { type = "list_item", text = "No Egg Scramble - Defeat Ula’tek before the Greasy Hatchling breaks in The Venomous Abyss on Normal difficulty or higher. – Greasy Hatchling unbroken (Reward: Companion Pet: Ula’took)", level = 0 },
            { type = "list_item", text = "Comforting Da Spirits - Experience an Ancestral Vision and comfort the trapped spirits scattered within in The Venomous Abyss on Normal difficulty or higher. -Talon Queen Rah’ven comforted -Farmer Su’mekaya comforted -Stone Grafter Babooi’jin comforted -Hexweaver Vola’ni comforted -Chef Mom’jin comforted -Trapper Haka’li comforted -Scout Jino’ka comforted -Shieldbearer Kora’man comforted", level = 0 },
            { type = "h2", text = "HEROIC DIFFICULTY AND HIGHER" },
            { type = "list_item", text = "Ahead of the Curve: Ula’tek ; defeat Ula’tek in The Venomous Abyss on Heroic difficulty or higher, before the release of the next raid tier.", level = 0 },
            { type = "h2", text = "MYTHIC DIFFICULTY" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-curse-of-ulatek-the-venomous-abyss-raid-now-live-7a43ed4dc7\\image-10.jpg" },
            { type = "p", text = "Primeval Skyfriend (Drop from Mythic Ula'tek)“The most vicious elder skyfiends lurk within the confines of the Venomous Abyss, surfacing only to stalk prey across the shores of Atal'Utek before returning to their fetid lairs. This one has become your sky-friend.”" },
            { type = "list_item", text = "Mythic: Nekzali the Soulcoiler - Defeat the Soulcoiler in The Venomous Abyss on Mythic difficulty.", level = 0 },
            { type = "list_item", text = "• Mythic: Entombed Sentinels - Defeat the Entombed Sentinels in The Venomous Abyss on Mythic difficult.", level = 0 },
            { type = "list_item", text = "• Mythic: The Lost Explorers - Defeat The Lost Explorers in The Venomous Abyss on Mythic difficulty.", level = 0 },
            { type = "list_item", text = "Mythic: Vashnik the Malignant - Defeat Vashnik the Malignant in The Venomous Abyss on Mythic difficulty.", level = 0 },
            { type = "list_item", text = "Mythic Sszorak -Defeat Ssorak in The Venomous Abyss on Mythic Difficulty.", level = 0 },
            { type = "list_item", text = "Mythic: The Coiled Altar - Defeat The Coiled Altar in The Venomous Abyss on Mythic difficulty.", level = 0 },
            { type = "list_item", text = "Mythic: Ulatek - Defeat Ula’tek in the Venomous Abyss on Mythic difficulty. (Reward—Title: Venom’s End)", level = 0 },
            { type = "list_item", text = "Cutting Edge: Ula’tek Defeat Ula’tek in the Venomous Abyss on Mythic difficulty before the release of the next Raid tier.", level = 0 },
            { type = "p", text = "Hall of Fame: Ula'tek- Be among the first two hundred guilds worldwide to defeat Ula'tek on Mythic difficulty. Title: \"Famed Slayer of Ula'tek\"" },
            { type = "hr" },
            { type = "h3", text = "Class Armor Sets" },
            { type = "p", text = "Visit the Midnight Season 2 Overview to view some of the available class armor sets from The Venomous Abyss and learn more about Season 2." },
            { type = "list_item", text = "Death Knight: Baleful Grave-Knight’s Crucible", level = 0 },
            { type = "list_item", text = "Demon Hunter: Abyssal Doomhound’s Pursuit", level = 0 },
            { type = "list_item", text = "Druid: Bark of the Enigmatic Dreamwatcher", level = 0 },
            { type = "list_item", text = "Evoker: : Echo of Calamity", level = 0 },
            { type = "list_item", text = "Hunter: Skulking Viper’s Ambush", level = 0 },
            { type = "list_item", text = "Mage: : Primal Leywarden’s Attire", level = 0 },
            { type = "list_item", text = "Monk: Guile of the Monkey King", level = 0 },
            { type = "list_item", text = "Paladin: Radiance of the Consecrated Flame", level = 0 },
            { type = "list_item", text = "Priest: Cosmic Penitent’s Raiment", level = 0 },
            { type = "list_item", text = "Rogue: Chosen Bloodslayer’s Hexweave", level = 0 },
            { type = "list_item", text = "Shaman: Ophidian Oracle’s Prophecy", level = 0 },
            { type = "list_item", text = "Warlock: Damned Necrolyte’s Shattered Restraints", level = 0 },
            { type = "list_item", text = "Warrior: Jade Warlord’s Dominion", level = 0 },
            { type = "hr" },
            { type = "p", text = "We look forward to joining you in the Venomous Abyss!" },
            },
        },
        ["2026-08-18-now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more-fa68d3f668"] = {
            id = "2026-08-18-now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more-fa68d3f668",
            post_key = "fa68d3f668",
            title = "Now Live: The Venomous Abyss Raid, Mythic+ and PvP Season 2, and More!",
            category = "Blogs (US)",
            timestamp = 1787075135,
            url = "https://news.blizzard.com/en-us/article/24294369/now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more",
            content = {
            { type = "p", text = "Steel your resolve, gather your allies, and descend into the darkness in Midnight Season 2. Brave the Venomous Abyss, conquer the new Mythic+ rotation, prove your mettle in PvP, delve deeper for dangerous rewards, stalk deadly new Prey across the Coiled Isle, face down World Bosses in Lairs, and so much more!" },
            { type = "h3", text = "Unlock Schedule" },
            { type = "p", text = "Week of August 11" },
            { type = "list_item", text = "Lair: The Tidebound Grotto - World Difficulty", level = 0 },
            { type = "list_item", text = "New Dungeon: Altar of Fangs", level = 0 },
            { type = "list_item", text = "Midnight Dungeons - Heroic and Mythic 0 difficulties (Mythic 0 is on a weekly reset and drops 292 item level gear).", level = 0 },
            { type = "list_item", text = "Fresh Dungeon Rotation - Altar of Fangs (New Dungeon), Murder Row, Den of Nalorakk, The Blinding Vale, Voidscar Arena, Kings' Rest (Battle for Azeroth), Temple of Sethraliss (Battle for Azeroth), and Ruby Life Pools (Dragonflight)", level = 0 },
            { type = "list_item", text = "Prey Season 2 - Normal and Hard Modes", level = 0 },
            { type = "list_item", text = "Delves Season 2 - Nemesis ? Difficulty, All Tiers, No Bountiful", level = 0 },
            { type = "list_item", text = "Training Grounds: Arenas", level = 0 },
            { type = "list_item", text = "Credit toward Great Vault Season 2 rewards begins.", level = 0 },
            { type = "p", text = "Week of August 18" },
            { type = "list_item", text = "NEW! The Venomous Abyss Raid - Normal, Heroic, Mythic, and Raid Finder Wing 1", level = 0 },
            { type = "list_item", text = "Mythic+ Season 2", level = 0 },
            { type = "list_item", text = "Mythic 0 is on a daily reset (drops 292 item level gear)", level = 0 },
            { type = "list_item", text = "PvP Season 2", level = 0 },
            { type = "list_item", text = "Delves Season 2 - Nemesis ?? Difficulty, Bountiful Delves, and Keys", level = 0 },
            { type = "list_item", text = "Prey Season 2 - Nightmare Mode and Curse of the Isle", level = 0 },
            { type = "list_item", text = "Great Vault Season 2 Gear becomes available.", level = 0 },
            { type = "list_item", text = "Lair: The Tidebound Grotto - Normal, Heroic and Mythic (Flexible-Scaling) Difficulties", level = 0 },
            { type = "p", text = "Week of August 25" },
            { type = "list_item", text = "The Venomous Abyss - Raid Finder Wing 2, Story Mode", level = 0 },
            { type = "p", text = "Week of September 1" },
            { type = "list_item", text = "The Venomous Abyss - Raid Finder Wing 3", level = 0 },
            { type = "p", text = "Week of September 8" },
            { type = "list_item", text = "The Venomous Abyss - Raid Finder Wing 4", level = 0 },
            { type = "hr" },
            { type = "h2", text = "RISE TO THE CHALLENGE IN MYTHIC+ SEASON 2 DUNGEONS" },
            { type = "p", text = "A new season means a new proving ground. Brave the halls of Altar of Fangs and conquer a fresh rotation of deadly dungeons to earn powerful rewards and lasting glory." },
            { type = "h3", text = "Season 2 Dungeon Unlock Schedule" },
            { type = "p", text = "Week of August 11: Heroic and Mythic Dungeon Difficulties and Fresh Dungeon RotationWeek of August 18: Mythic+ Season 2" },
            { type = "p", text = "Face a fresh Mythic+ dungeon rotation in Season 2, featuring the new Altar of Fangs and a deadly lineup of challenges from across Azeroth." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more-fa68d3f668\\image-1.jpg" },
            { type = "list_item", text = "New! Altar of Fangs ( Midnight )", level = 0 },
            { type = "list_item", text = "Murder Row ( Midnight )", level = 0 },
            { type = "list_item", text = "Den of Nalorakk ( Midnight )", level = 0 },
            { type = "list_item", text = "The Blinding Vale ( Midnight )", level = 0 },
            { type = "list_item", text = "Voidscar Arena ( Midnight )", level = 0 },
            { type = "list_item", text = "Ruby Life Pools ( Dragonflight )", level = 0 },
            { type = "list_item", text = "Kings' Rest ( Battle for Azeroth )", level = 0 },
            { type = "list_item", text = "Temple of Sethraliss ( Battle for Azeroth )", level = 0 },
            { type = "h3", text = "Conquer New Challenges, Claim New Rewards" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more-fa68d3f668\\image-2.jpg" },
            { type = "p", text = "Breath of Blight (Left) \"A sickly haze trails in its wake, poisoning earth, air, and anything foolish enough to pursue it.\"Breath of Ruin (Right)\"Where its shadow falls, even the bravest hear the echo of forgotten wars.\"" },
            { type = "list_item", text = "Midnight Keystone Conqueror: Season 2 (Feat of Strength)", level = 0 },
            { type = "list_item", text = "Title: “the Venomous”", level = 1 },
            { type = "list_item", text = "Attain a Mythic+ Rating of at least 1500 during Midnight Season 2.", level = 2 },
            { type = "list_item", text = "Midnight Keystone Master: Season 2 (Feat of Strength)", level = 0 },
            { type = "list_item", text = "Mount Reward: Breath of Blight", level = 1 },
            { type = "list_item", text = "Attain a Mythic+ Rating of at least 2000 during Midnight Season 2.", level = 2 },
            { type = "list_item", text = "Midnight Keystone Legend: Season 2 (Feat of Strength)", level = 0 },
            { type = "list_item", text = "Mount Reward: Breath of Ruin", level = 1 },
            { type = "list_item", text = "Attain a Mythic+ Rating of at least 3000 during Midnight Season 2.", level = 2 },
            { type = "list_item", text = "Midnight Keystone Myth: Season 2", level = 0 },
            { type = "list_item", text = "Title: “the Venomous Contender”", level = 1 },
            { type = "list_item", text = "Venomous Champion: Midnight Season 2 (Feat of Strength)", level = 0 },
            { type = "list_item", text = "End Midnight Mythic+ Season 2 with a Mythic+ Rating in the top 1% of all players in your region.", level = 1 },
            { type = "list_item", text = "Venomous Hero: Midnight Season 2", level = 0 },
            { type = "list_item", text = "Title: “the Venomous Hero”", level = 1 },
            { type = "list_item", text = "End Midnight Mythic+ Season 2 with a Mythic+ Rating in the top 0.1% of all players in your region.", level = 1 },
            { type = "p", text = "Players can also gain access to Dungeon portals for each of the eight dungeons when they complete Mythic 10 or higher within the time limit." },
            { type = "hr" },
            { type = "h2", text = "RAID THE VENOMOUS ABYSS FOR GLORY AND REWARDS" },
            { type = "p", text = "Guided by the dark whispers of Malacrass, Zul’jan has freed the forgotten broods of Ula’tek from their prison. As the monster’s power grows, Zul’jarra calls upon the Champions of Azeroth to descend into the Vaults of Atal’Utek to stop her brother before the weapon is unleashed on the world." },
            { type = "h3", text = "Venomous Abyss Unlock Schedule" },
            { type = "p", text = "Week of August 18: Normal, Heroic, Mythic, and Raid Finder Wing 1Week of August 25: Story Mode and Raid Finder Wing 2Week of September 1: Raid Finder Wing 3Week of September 8: Raid Finder Wing 4" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-18-now-live-the-venomous-abyss-raid-mythic-and-pvp-season-2-and-more-fa68d3f668\\image-3.jpg" },
            { type = "h3", text = "The Spoils of the Venomous Abyss" },
            { type = "p", text = "Claim powerful class sets, trophies, titles, and more from the depths of The Venomous Abyss. Do you dare enter to claim the spoils?" },
            { type = "h2", text = "CLASS ARMOR SETS" },
