            url = "https://eu.forums.blizzard.com/en/wow/t/625790/1",
            content = {
            { type = "p", text = "hello , blizzard" },
            { type = "p", text = "why i dont have 3x spark my bag i saw many player have 3 spark" },
            { type = "p", text = "in my bag i have 1 spark" },
            },
        },
        ["2026-08-14-some-people-can-get-3-sparks-this-week-and-others-only-2-ae13b368fb"] = {
            id = "2026-08-14-some-people-can-get-3-sparks-this-week-and-others-only-2-ae13b368fb",
            post_key = "ae13b368fb",
            title = "Some people can get 3 sparks this week and others only 2",
            category = "General Discussion (US)",
            timestamp = 1786732217,
            url = "https://us.forums.blizzard.com/en/wow/t/2335523/1",
            content = {
            { type = "p", text = "The curse surge quest or collect 100 void whispers gives a spark for pve" },
            { type = "p", text = "Sparks of war in voidstorm or naigtal gives the second spark for the week via pvp." },
            { type = "p", text = "However, if you never did the midnight tour quest, to do all the faction community events, you can get a 3rd spark from that and be ahead of everyone else immediately on crafting items next week." },
            },
        },
        ["2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca"] = {
            id = "2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca",
            post_key = "17589c62ca",
            title = "WoW Weekly: Curse of Ula'tek, Blueprints, Endeavors, and More!",
            category = "Blogs (EU)",
            timestamp = 1786727719,
            url = "https://news.blizzard.com/en-gb/article/24295094/wow-weekly-curse-of-ula-tek-blueprints-endeavors-and-more",
            content = {
            { type = "p", text = "Each week brings you adventurous discovery and fresh rewards—be sure to check in to learn more about what awaits you in Azeroth." },
            { type = "hr" },
            { type = "h2", text = "CURSE OF ULA’TEK NOW LIVE! JOURNEY TO THE COILED ISLE" },
            { type = "p", text = "A new threat coils in the shadows as the Curse of Ula’tek content update draws champions to the Coiled Isle." },
            { type = "p", text = "Uncover the secrets buried within its cursed depths as the Midnight Campaign continues, face venomous new dangers in a new raid and dungeon, prepare for fresh challenges when Midnight Season 2 begins, and much more!" },
            { type = "p", text = "Mind the venom, and we’ll see you on the Coiled Isle!" },
            { type = "p", text = "Click to Learn More" },
            { type = "hr" },
            { type = "h2", text = "MIDNIGHT: CURSE OF ULA'TEK PRE-SEASON DETAILS" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-1.jpg" },
            { type = "p", text = "The Curse of Ula’tek content update is now live, and you still have time during this pre-season week to hunt Rares, seek rewards, gear up, and more!" },
            { type = "p", text = "While Midnight Season 2 is in a pre-season state, certain content and rewards are not yet available." },
            { type = "p", text = "For more details on what’s coming with the Curse of Ula’tek content update, read our Curse of Ula’tek overview, and find the full Season 2 unlock schedule, including pre-season details, in our previously published article." },
            { type = "p", text = "Click to Learn More" },
            { type = "hr" },
            { type = "h2", text = "TWITCH DROP NOW LIVE! GET THE ENSEMBLE: SORCERER'S GRASSY GARB TRANSMOG" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-2.jpg" },
            { type = "p", text = "Watch 4 hours of eligible World of Warcraft content on any channel on Twitch.tv from now until September 8 at 10:00 am PDT while these Twitch Drops are active to claim the Ensemble:Sorcerer's Grassy Garb transmog set." },
            { type = "p", text = "Start Time: 11 August at 18:00 am BSTEnd Time: 8 September at 18:00 am BST" },
            { type = "p", text = "Frequently asked questions and details on linking your Twitch account can be found in our previously published article." },
            { type = "p", text = "Click to Learn More" },
            { type = "hr" },
            { type = "h2", text = "CURSE OF ULA'TEK HOUSING UPDATES: NEW BLUEPRINTS, PETS, AND MORE ARRIVE FOR YOUR HOME" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-3.jpg" },
            { type = "p", text = "The Curse of Ula’tek update brings new ways to shape, share, and settle into your Housing space. With Blueprints to save and swap your favorite builds, Pet Beds to welcome your trusted companions indoors, and a variety of new updates to expand your decorating options, your home is ready for a little more personality." },
            { type = "p", text = "Blueprints let you capture a favorite Housing layout and keep it ready for whenever inspiration strikes. Save a single room, your interior, your exterior, or your entire home, then swap between builds any time you want to refresh a space, test a new idea, or return to an old favorite without rebuilding it from scratch." },
            { type = "p", text = "Visit your neighborhood vendors, gather your favorite companions, and stop by the official forums to find and share Blueprints with other players—then let your creativity run wild as you make your home into a space worth saving, sharing, and showing off with the Housing updates in Curse of Ula’tek." },
            { type = "p", text = "Click to Learn More" },
            { type = "hr" },
            { type = "h2", text = "UNDERTAKE FOUR NEW ENDEAVORS IN YOUR NEIGHBORHOOD!" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-4.jpg" },
            { type = "p", text = "Your neighborhood is about to receive new visitors, each bringing a variety of tasks, stories, and items to purchase. Meet back up with Griftah for “fine Amani items”, lend a helping hand to the Ohn’ahran centaurs, attend a candle-making workshop with the kobolds of the Ringing Deeps, and relax with the worldly tortollans." },
            { type = "p", text = "With the launch of Curse of Ula’tek, the Knock-off Amani Endeavor is available immediately and ties into activities on the Coiled Isle. After that, you’ll be able to choose from an array of Endeavors as new visitors make their way to your neighborhood." },
            { type = "p", text = "Players may also notice new additions around their Neighborhood based on the Endeavors they have completed, both old and new, so keep an eye out during your visits. We look forward to seeing you in the neighborhood!" },
            { type = "p", text = "Click to Learn More" },
            { type = "hr" },
            { type = "h2", text = "EPIC SAVINGS AWAIT ON MIDNIGHT™ AND MORE!" },
            { type = "p", text = "Battle.net Game Deals are back, bringing limited-time savings on World of Warcraft®: Midnight™, select game services, and more!" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-5.jpg" },
            { type = "p", text = "With up to 40% off World of Warcraft: Midnight, it's time to return to the legendary kingdom of Quel’Thalas, explore new and reimagined zones, join the fight against Xal’atath in the battle between Light and Void, and put down roots in your own cozy corner of Azeroth with Housing." },
            { type = "p", text = "Adventure is Calling" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-6.jpg" },
            { type = "p", text = "Control your destiny with up to 33% off on World of Warcraft: Midnight Game Services, including the Enhanced Level 80 Character Boost, Name Changes, Race Changes, Faction Change Packs, and Paid Character Transfers." },
            { type = "p", text = "Shop Game Services" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-14-wow-weekly-curse-of-ulax27tek-blueprints-endeavors-and-more-17589c62ca\\image-7.jpg" },
            { type = "p", text = "Celebrate 30 years of Warcraft history and travel back to the beginning with remastered versions of the adventures that laid the foundation for Azeroth’s most epic stories!" },
            { type = "p", text = "Relive the Legend" },
            { type = "hr" },
            { type = "p", text = "Let us journey alongside you, regale you with tales of adventure in faraway places, map out roads less traveled, and direct your gaze toward the legendary challenges that await. Return each week to the World of Warcraft news site, where together, we'll uncover your destiny." },
            },
        },
