        ["2026-08-10-undertake-four-new-endeavors-in-your-neighborhood-76b6b15217"] = {
            id = "2026-08-10-undertake-four-new-endeavors-in-your-neighborhood-76b6b15217",
            post_key = "76b6b15217",
            title = "Undertake Four New Endeavors in Your Neighborhood!",
            category = "Blogs (EU)",
            timestamp = 1786382115,
            url = "https://news.blizzard.com/en-gb/article/24296054/undertake-four-new-endeavors-in-your-neighborhood",
            content = {
            { type = "p", text = "Your neighborhood is about to receive new visitors, each bringing a variety of tasks, stories, and items to purchase. Meet back up with Griftah for “fine Amani items”, lend a helping hand to the Ohn’ahran centaurs, attend a candle making workshop with the kobolds of the Ringing Deeps, and relax with the worldly tortollans." },
            { type = "p", text = "With the launch of Curse of Ula’tek, the Knock-off Amani Endeavor is available immediately and ties into activities on the Coiled Isle. After that, you’ll be able to choose from an array of Endeavors as new visitors make their way to your neighborhood." },
            { type = "hr" },
            { type = "h2", text = "AMANI TROLLS: KNOCK-OFF AMANI" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-10-undertake-four-new-endeavors-in-your-neighborhood-76b6b15217\\image-1.jpg" },
            { type = "p", text = "While this endeavor is active, players will be able to access a portal directly to The Coiled Isle." },
            { type = "p", text = "Vendor: GriftahNew Currency: Griftah’s Token of Appreciation- “Griftah may generously give one of these as a reward for completing an endeavor task, depending on its difficulty. Trade it with Griftah in your Neighborhood for exciting (or not) prizes.”" },
            { type = "p", text = "Item Name" },
            { type = "p", text = "Item Type" },
            { type = "p", text = "Item Cost" },
            { type = "p", text = "Bag of Totally Legitimate Amani Goods" },
            { type = "p", text = "A variety of Amani items, supposedly. These may be of interest to your neighbors." },
            { type = "p", text = "1 Griftah’s Token of Appreciation" },
