        ["2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab"] = {
            id = "2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab",
            post_key = "6e415863ab",
            title = "Get Ready for a Showdown in August’s Trading Post",
            category = "Blogs (EU)",
            timestamp = 1786185484,
            url = "https://news.blizzard.com/en-gb/article/24294061/get-ready-for-a-showdown-in-augusts-trading-post",
            content = {
            { type = "p", text = "August’s Trading Post is ready for a showdown, bringing a lineup of mounts, transmogs, weapons, and black and white styles to add a striking new look to your collection. Players can complete activities to earn Trader’s Tender and fill the Traveler’s Log to take aim with this month’s bonus reward—the Ensemble: Midnight Outlaw transmog set." },
            { type = "hr" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-1.jpg" },
            { type = "image", width = 720, height = 387, u = 0.703125, v = 0.755859, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-2.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-3.jpg" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-4.jpg" },
            { type = "p", text = "Visit T&W** (Tawney and Wilder) just outside the Mage District in Stormwind or the Zen’shiri Trading Post next to Grommash Hold in Orgrimmar to check out all the latest items*** they have available. Players can also visit the Trading Post in the capital cities of Dornogal (The Foregrounds) on the Isle of Dorn and in the renewed Silvermoon City where representatives of both Tawney and Wilder and the Zen’shiri Trading Post are open for business." },
            { type = "hr" },
            { type = "h2", text = "CHECK OUT WHAT'S IN STOCK FOR AUGUST" },
            { type = "h2", text = "MOUNTS" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-5.jpg" },
            { type = "p", text = "Hateforged BlazecycleMount“This sweet deathcycle lets you go on your very own burning rubber crusade!”" },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-6.jpg" },
            { type = "p", text = "Badlands BuzzardMount“The white buzzards are some of the rarest in all the Badlands. Rumor has it that one may even be caught and tamed to fight alongside hunters.”" },
            { type = "p", text = "This month, the previous promotional mount, Hateforged Blazecycle, arrives on the Trading Post for the first time." },
