            { type = "image", width = 254, height = 420, u = 0.992188, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-15.jpg" },
            { type = "image", width = 254, height = 420, u = 0.992188, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-get-ready-for-a-showdown-in-augusts-trading-post-6e415863ab\\image-16.jpg" },
