        ["2026-08-08-world-of-warcraft-midnight-comic-legacy-of-rage-701a627d9d"] = {
            id = "2026-08-08-world-of-warcraft-midnight-comic-legacy-of-rage-701a627d9d",
            post_key = "701a627d9d",
            title = "World of Warcraft: Midnight Comic, “Legacy of Rage”",
            category = "Blogs (EU)",
            timestamp = 1786185467,
            url = "https://news.blizzard.com/en-gb/article/24295084/world-of-warcraft-midnight-comic-legacy-of-rage",
            content = {
            { type = "p", text = "The young Amani troll, Zul’jan, finds himself caught between his people’s fading legacy and the dangerous temptation of ancient power. As memories of his childhood clash with the harsh realities of the present, Zul’jan is guided down this new path by a mysterious mentor, exploring his grandfather’s legacy, fractured loyalties, and the promise of a new Amani rise—but it remains to be seen whose benefit this journey is truly for." },
            { type = "p", text = "Read By: Yeukayi Ushe as Zul’janWritten By: Robert BrooksArt & Cover: Marco Del FornoColors: Mauro GulmaLetters: AndWorld Design" },
            { type = "h3", text = "Downloadable PDF" },
            { type = "hr" },
            { type = "p", text = "Read more stories and stay up to date on the latest World of Warcraft news at worldofwarcraft.blizzard.com/news." },
            },
        },
