        ["2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a"] = {
            id = "2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a",
            post_key = "150e51466a",
            title = "Keep Track of Potions, Trinkets and More with New User Interface Updates",
            category = "Blogs (EU)",
            timestamp = 1786185429,
            url = "https://news.blizzard.com/en-gb/article/24294064/keep-track-of-potions-trinkets-and-more-with-new-user-interface-updates",
            content = {
            { type = "p", text = "Curse of Ula’tek introduces user interface updates designed to help you better track your cooldowns, consumables, and key combat information when it matters most." },
            { type = "hr" },
            { type = "h2", text = "STAY IN CONTROL WITH THE COOLDOWN MANAGER" },
            { type = "p", text = "With the new updates, the Cooldown Manager will now be able to track trinkets and potions helping with consumable management. It can also track racial ability cooldowns and durations." },
            { type = "image", width = 343, height = 420, u = 0.669922, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a\\image-1.jpg" },
            { type = "image", width = 343, height = 420, u = 0.669922, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a\\image-2.jpg" },
            { type = "p", text = "For managing other resources, more updates arrive to the ping system. Players can ping their action bar or the Cooldown Manager directly providing your team with the status of your spells." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a\\image-3.jpg" },
            { type = "p", text = "Your own unit frames can also get pinged to convey the status of your health to the group and players who are acting in a healing role will also share the status of their mana saving them from needing to say, “OOM” before the next pull." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a\\image-4.jpg" },
            { type = "hr" },
            { type = "h2", text = "KEEP THE HEALS FLOWING WITH NEW CONFIGURATIONS" },
            { type = "image", width = 398, height = 420, u = 0.777344, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-150e51466a\\image-5.jpg" },
            { type = "p", text = "Healers can now configure or hide the buffs shown on Raid Frames, so the healing effects that matter most to you stay visible." },
            { type = "hr" },
            { type = "p", text = "We’ll see you in-game as you put these updates to use with your party and raid team." },
            },
        },
        ["2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc"] = {
            id = "2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc",
            post_key = "7f905643cc",
            title = "Keep Track of Potions, Trinkets and More with New User Interface Updates",
            category = "Blogs (US)",
            timestamp = 1786185421,
            url = "https://news.blizzard.com/en-us/article/24294064/keep-track-of-potions-trinkets-and-more-with-new-user-interface-updates",
            content = {
            { type = "p", text = "Curse of Ula’tek introduces user interface updates designed to help you better track your cooldowns, consumables, and key combat information when it matters most." },
            { type = "hr" },
            { type = "h2", text = "STAY IN CONTROL WITH THE COOLDOWN MANAGER" },
            { type = "p", text = "With the new updates, the Cooldown Manager will now be able to track trinkets and potions helping with consumable management. It can also track racial ability cooldowns and durations." },
            { type = "image", width = 343, height = 420, u = 0.669922, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc\\image-1.jpg" },
            { type = "image", width = 343, height = 420, u = 0.669922, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc\\image-2.jpg" },
            { type = "p", text = "For managing other resources, more updates arrive to the ping system. Players can ping their action bar or the Cooldown Manager directly providing your team with the status of your spells." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc\\image-3.jpg" },
            { type = "p", text = "Your own unit frames can also get pinged to convey the status of your health to the group and players who are acting in a healing role will also share the status of their mana saving them from needing to say, “OOM” before the next pull." },
            { type = "image", width = 720, height = 405, u = 0.703125, v = 0.791016, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc\\image-4.jpg" },
            { type = "hr" },
            { type = "h2", text = "KEEP THE HEALS FLOWING WITH NEW CONFIGURATIONS" },
            { type = "image", width = 398, height = 420, u = 0.777344, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-keep-track-of-potions-trinkets-and-more-with-new-user-interface-update-7f905643cc\\image-5.jpg" },
            { type = "p", text = "Healers can now configure or hide the buffs shown on Raid Frames, so the healing effects that matter most to you stay visible." },
            { type = "hr" },
            { type = "p", text = "We’ll see you in-game as you put these updates to use with your party and raid team." },
            },
        },
        ["2026-08-08-housing-dye-trading-temporarily-disabled-291b5190ef"] = {
            id = "2026-08-08-housing-dye-trading-temporarily-disabled-291b5190ef",
            post_key = "291b5190ef",
            title = "Housing Dye Trading Temporarily Disabled",
            category = "Housing (US)",
            timestamp = 1786185417,
            url = "https://us.forums.blizzard.com/en/wow/t/2332674/1",
            content = {
            { type = "p", text = "Starting tomorrow, Tuesday August 4 at, at 1:00 p.m. PDT (4:00 p.m. EDT), all housing dye items will be temporarily adjusted to become Warbound. This will not change how the items are created or used or purchased on the Auction House, but it will prevent players from posting any new housing dye auctions." },
            { type = "p", text = "Our goal is to ensure that no housing dyes are up for sale on the Auction House during the deployment of the Curse of Ula’tek content update, to alleviate issues with the upcoming dye conversion." },
            { type = "p", text = "After the Curse of Ula’tek content update goes live and all existing housing dye and housing dye pigment items are converted to the new housing dye items, players will once again be able to freely trade, sell, or auction the new housing dye items." },
            { type = "p", text = "We appreciate your patience as we prepare for this changeover." },
            },
        },
        ["2026-08-08-housing-dye-trading-temporarily-disabled-f8119d40fb"] = {
            id = "2026-08-08-housing-dye-trading-temporarily-disabled-f8119d40fb",
            post_key = "f8119d40fb",
            title = "Housing Dye Trading Temporarily Disabled",
            category = "Housing (EU)",
            timestamp = 1786185413,
            url = "https://eu.forums.blizzard.com/en/wow/t/625049/1",
            content = {
            { type = "p", text = "Starting tomorrow, Tuesday August 4 at, at 22:00 CEST, all housing dye items will be temporarily adjusted to become Warbound. This will not change how the items are created or used or purchased on the Auction House, but it will prevent players from posting any new housing dye auctions." },
            { type = "p", text = "Our goal is to ensure that no housing dyes are up for sale on the Auction House during the deployment of the Curse of Ula’tek content update, to alleviate issues with the upcoming dye conversion." },
            { type = "p", text = "After the Curse of Ula’tek content update goes live and all existing housing dye and housing dye pigment items are converted to the new housing dye items, players will once again be able to freely trade, sell, or auction the new housing dye items." },
            { type = "p", text = "We appreciate your patience as we prepare for this changeover." },
            },
        },
        ["2026-08-08-season-2-ends-on-august-17-21485e5cc0"] = {
            id = "2026-08-08-season-2-ends-on-august-17-21485e5cc0",
            post_key = "21485e5cc0",
            title = "Season 2 Ends on August 17",
            category = "The Burning Crusade Classic (US)",
            timestamp = 1786185406,
            url = "https://us.forums.blizzard.com/en/wow/t/2332698/1",
            content = {
            { type = "p", text = "The current Burning Crusade Classic Anniversary PvP season is coming to an end." },
            { type = "p", text = "In this region, Season 2 will end at 10:00 p.m. PDT on Monday, August 17. (1:00 a.m. EDT Tuesday, August 18)" },
            { type = "p", text = "Burning Crusade PvP Season 3 will start with the weekly reset on Tuesday, September 1. At that time, Season 2 rewards will be distributed." },
            { type = "p", text = "Have a good fight to the finish!" },
            },
        },
        ["2026-08-08-season-2-ends-on-august-18-c3be70cc71"] = {
            id = "2026-08-08-season-2-ends-on-august-18-c3be70cc71",
            post_key = "c3be70cc71",
            title = "Season 2 Ends on August 18",
            category = "The Burning Crusade Classic (EU)",
            timestamp = 1786185401,
            url = "https://eu.forums.blizzard.com/en/wow/t/625052/1",
            content = {
            { type = "p", text = "The current Burning Crusade Classic Anniversary PvP season is coming to an end." },
            { type = "p", text = "In this region, Season 2 will end at 22:00 CEST on Tuesday, August 18." },
            { type = "p", text = "Burning Crusade PvP Season 3 will start with the weekly reset on Wednesday, September 2. At that time, Season 2 rewards will be distributed." },
            { type = "p", text = "Have a good fight to the finish!" },
            },
        },
        ["2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed"] = {
            id = "2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed",
            post_key = "5e85ffb7ed",
            title = "Curse of Ula’tek: Link Your Battle.net Account to Discord",
            category = "Blogs (EU)",
            timestamp = 1786185398,
            url = "https://news.blizzard.com/en-gb/article/24296228/curse-of-ulatek-link-your-battle-net-account-to-discord",
            content = {
            { type = "p", text = "In the Curse of Ula’tek update we’re introducing a new Discord integration allowing you to speak with your guildmates both in and out of the game by connecting your Battle.net and Discord accounts. Whether you’re coordinating your next raid run, looking for more to join you in game for PvP, or just hanging out in your neighborhoods together, you’ll be able to send messages between the two quickly and easily." },
            { type = "hr" },
            { type = "h2", text = "LINKING YOUR WORLD OF WARCRAFT AND DISCORD ACCOUNTS" },
            { type = "p", text = "To connect your Discord account to your Battle.net account, you’ll begin by opening up the Game Menu (Escape) and opening Options. In the Social Tab, a new option will show to Enable Discord Functionality." },
            { type = "image", width = 532, height = 420, u = 0.519531, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-1.jpg" },
            { type = "p", text = "When you choose to connect your account to Discord, you’ll be taken to some additional screens to finalize the connection. Make sure you’re logged into Discord before attempting to connect your accounts, it will ask you to confirm the connection as well." },
            { type = "image", width = 720, height = 358, u = 0.703125, v = 0.699219, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-2.jpg" },
            { type = "image", width = 720, height = 388, u = 0.703125, v = 0.757812, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-3.jpg" },
            { type = "image", width = 720, height = 355, u = 0.703125, v = 0.693359, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-4.jpg" },
            { type = "hr" },
            { type = "h2", text = "SETTING UP DISCORD AS AN ADMINISTRATOR AND GUILD LEADER" },
            { type = "p", text = "Administrators of a guild Discord will first need to make sure they enable the appropriate channel permissions in order to connect their guild chat to their chosen Discord chat channel. These permissions are as follows:" },
            { type = "list_item", text = "Manage Channels – Ability to edit channel settings", level = 0 },
            { type = "list_item", text = "View Channel – Can see and read the channel", level = 0 },
            { type = "list_item", text = "Send Messages – Can post messages in the channel", level = 0 },
            { type = "p", text = "The rest of your connection can be performed within World of Warcraft by either the guild leader or officers with the correct permissions." },
            { type = "p", text = "Instructions to link your Guild to a Discord channel on WoW:" },
            { type = "list_item", text = "Open the Guild & Communities UI with the (J) hotkey.", level = 0 },
            { type = "list_item", text = "Select the Roster tab on the right side of the panel.", level = 0 },
            { type = "list_item", text = "Select \"Guild Settings\" on the bottom right of the panel.", level = 0 },
            { type = "list_item", text = "Under the Guild Control dropdown select Discord Settings.", level = 0 },
            { type = "list_item", text = "In this window you will see all Discord servers you belong to and be able to select the specific channels that have linking permissions available.", level = 0 },
            { type = "list_item", text = "Click a server to select it.", level = 0 },
            { type = "list_item", text = "Select a linkable channel from the dropdown and click the link.", level = 0 },
            { type = "list_item", text = "You can also create a separate Discord chat into its own channel within World of Warcraft.", level = 0 },
            { type = "image", width = 320, height = 420, u = 0.625, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-5.jpg" },
            { type = "image", width = 320, height = 420, u = 0.625, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-6.jpg" },
            { type = "hr" },
            { type = "h2", text = "CHAT BETWEEN DISCORD AND YOUR GUILD CHAT" },
            { type = "p", text = "Once you’re connected, you’re ready to chat. You’ll easily be able to identify when a message has been sent from Discord or sent from within the game and be able to adjust your chat tabs accordingly so you can always keep an eye on what your guild is doing whether you’re in game or out." },
            { type = "image", width = 374, height = 324, u = 0.730469, v = 0.632812, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-7.jpg" },
            { type = "image", width = 720, height = 304, u = 0.703125, v = 0.59375, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-8.jpg" },
            { type = "p", text = "If a player hasn’t linked their account to Discord, it will not show in-game messages in the Discord chat and will display as follows:" },
            { type = "image", width = 510, height = 140, u = 0.996094, v = 0.546875, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-9.jpg" },
            { type = "p", text = "You’ll also be able to choose the character name you want to display when chat messages arrive from Discord by selecting it from the Display Name drop down." },
            { type = "list_item", text = "Default: Use game-defined default, currently Last Online Character.", level = 0 },
            { type = "list_item", text = "Last Online Character Name: Use the last online character for your Battle.net account in this guild.", level = 0 },
            { type = "list_item", text = "Discord Global Name: Use your Global Name from Discord.", level = 0 },
            { type = "image", width = 548, height = 420, u = 0.535156, v = 0.820312, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-10.jpg" },
            { type = "p", text = "Guild leaders will have the option to modify settings at any time in the guild Discord settings to filter chat so that Discord traffic goes to a regular /guild chat channel or into a new dedicated guild /discord channel." },
            { type = "image", width = 720, height = 346, u = 0.703125, v = 0.675781, file = "Interface\\AddOns\\BluePosts\\Media\\Posts\\2026-08-08-curse-of-ulatek-link-your-battlenet-account-to-discord-5e85ffb7ed\\image-11.jpg" },
            { type = "hr" },
            { type = "p", text = "Join the conversation as this new integration goes live with the Curse of Ula’tek content update." },
            },
        },
