            { type = "p", text = "Sea-Dwelling Isle Serpent" },
            { type = "p", text = "Flying Mount" },
            { type = "p", text = "2,500 Coiled Filament and Bloodsworn Crew or above with Captain Tokka’s Crew" },
            { type = "p", text = "Envenomed Deathblade" },
            { type = "p", text = "Two-Hand Sword" },
            { type = "p", text = "500 Coiled Filament and Bloodsworn Crew or above with Captain Tokka’s Crew." },
            { type = "p", text = "Envenomed Game Ripper" },
            { type = "p", text = "Polearm" },
            { type = "p", text = "1,000 Coiled Filament and Bloodsworn Crew or above with Captain Tokka’s Crew." },
            { type = "p", text = "Envenomed Gavel" },
