        ["2026-07-17-user-interface-updates-in-classic-982d355fba"] = {
            id = "2026-07-17-user-interface-updates-in-classic-982d355fba",
            post_key = "982d355fba",
            title = "User Interface Updates in Classic",
            category = "Classic Discussion (US)",
            timestamp = 1784328480,
            url = "https://us.forums.blizzard.com/en/wow/t/2325408/1",
            content = {
            { type = "h2", text = "UPDATE JULY 17" },
            { type = "p", text = "With hotfixes that are now live, the following have been added to Burning Crusade Classic:" },
            { type = "h2", text = "USER INTERFACE" },
            { type = "list_item", text = "Raid Frames", level = 0 },
            { type = "list_item", text = "Added interface options for Raid Frames to select health bar color and background color.", level = 1 },
            { type = "list_item", text = "Added interface options for Raid Frames to show or hide dispellable debuff indicators (default: off).", level = 1 },
            { type = "list_item", text = "Edit Mode: Added Layout Template, Opacity, and Aura Icon Size options to Raid Frames", level = 1 },
            { type = "list_item", text = "Edit Mode: Fixed a bug where some aura icons would appear larger in the Edit Mode Raid Frame preview.", level = 1 },
            { type = "list_item", text = "Nameplates", level = 0 },
            { type = "list_item", text = "Added interface option to color friendly or enemy nameplates based on player class color.", level = 1 },
            { type = "list_item", text = "Fixed a bug where the item comparison tooltip was always showing, instead of only showing when you held down Shift.", level = 0 },
            { type = "p", text = "Hello," },
            { type = "p", text = "This week, we updated Burning Crusade Classic Anniversary from patch 2.5.5 to patch 2.5.6. Although this patch was almost entirely to support critical service systems, it also included changes to nameplates and raid frames. We’d like to tell you about these changes, highlight options you have to edit some of the user interface (UI), and look forward to patch 1.15.9 coming to WoW Classic soon." },
            { type = "h3", text = "UI Using Shared Code" },
            { type = "p", text = "All versions of WoW Classic share code with modern World of Warcraft. The games gain significant benefits from this, including the support of modern hardware, additional options for graphics and accessibility, widescreen support, and the ability to integrate with Battle.net services in the first place." },
            { type = "p", text = "This shared code also allows the introduction of UI elements to fill gaps in the original World of Warcraft UI. For instance, the original Burning Crusade only supported the “drag out” raid group UI from the Raid Frame. With the release of WoW Classic in 2019, the game included an additional option to use raid frames from modern World of Warcraft. This means that WoW Classic launched in 2019 with Battle for Azeroth’s raid frames, and then with patch 2.5.5, Burning Crusade Classic Anniversary utilized frames from The War Within. With patch 2.5.6, the game’s raid frame option has aligned with updates to modern World of Warcraft, now matching the offering from Midnight." },
            { type = "h3", text = "Modifications Using Chat Commands" },
            { type = "p", text = "Since we released patch 2.5.6, we’ve been listening to community feedback, and we recognize that players are looking for ways to modify their nameplates and raid frames that were updated. In addition to the settings that exist in the Options menu, players can use the following chat commands for further customization:" },
            { type = "list_item", text = "Nameplate Class Color (Enemy Units):", level = 0 },
            { type = "p", text = "/script C_CVar.SetCVar(\"nameplateShowClassColor\", 1);" },
            { type = "list_item", text = "Nameplate Class Color (Friendly Units):", level = 0 },
            { type = "p", text = "/script C_CVar.SetCVar(\"nameplateShowFriendlyClassColor\", 1);" },
            { type = "list_item", text = "Disabling Raid Frame Dispel Highlights:", level = 0 },
            { type = "p", text = "/script C_CVar.SetCVar(\"raidFramesDispelIndicatorOverlay\", 0);" },
            { type = "p", text = "We’re currently working on surfacing these settings in the Options menu itself, so that players will have access to them there, in addition to the option to use chat commands. We expect to implement this next week." },
            { type = "h3", text = "Upcoming WoW Classic Patch 1.15.9 – Week of July 19" },
            { type = "p", text = "Similar to this week’s Burning Crusade Classic Anniversary patch, the WoW Classic games (Classic Era, Season of Discovery, Hardcore) will receive a similar patch with the start of weekly regional maintenance the week of July 19. As with the Burning Crusade Classic Anniversary patch, this patch will bring in Edit Mode and changes to players’ nameplates and raid frames to the WoW Classic games." },
            { type = "p", text = "Some third-party addons may experience errors until they are updated by their authors. As all versions of World of Warcraft share most of their UI code, the addon API in 1.15.9 very closely matches the addon API from 2.5.6. For addon authors, we encourage you to use 2.5.6 as an environment for updating addons to be compatible with 1.15.9." },
            { type = "p", text = "We will continue to refine our updates in the future, so that we’re providing additional options for players to modify settings wherever possible." },
            { type = "p", text = "Thank you, as always, for your passion and feedback." },
            },
        },
        ["2026-07-17-feedback-midnight-season-2-dungeon-test-july-14th-july-20th-661e2294bc"] = {
            id = "2026-07-17-feedback-midnight-season-2-dungeon-test-july-14th-july-20th-661e2294bc",
            post_key = "661e2294bc",
            title = "Feedback: Midnight Season 2 Dungeon Test July 14th - July 20th",
            category = "Midnight: Curse of Ula'tek Public Test Realm (US)",
            timestamp = 1784320438,
            url = "https://us.forums.blizzard.com/en/wow/t/2326860/1",
            content = {
            { type = "p", text = "Greetings!" },
            { type = "p", text = "Midnight Season 2 dungeon testing continues on Tuesday, July 14th. The following dungeons are available for testing during this period:" },
            { type = "list_item", text = "Altar of Fangs", level = 0 },
            { type = "list_item", text = "Murder Row", level = 0 },
            { type = "list_item", text = "Den of Nalorakk", level = 0 },
            { type = "list_item", text = "Voidscar Arena", level = 0 },
            { type = "list_item", text = "The Blinding Vale", level = 0 },
            { type = "list_item", text = "Temple of Sethraliss", level = 0 },
            { type = "list_item", text = "Kings’ Rest", level = 0 },
            { type = "list_item", text = "Ruby Life Pools", level = 0 },
            { type = "p", text = "During the test period you’ll be able to acquire and customize Mythic Keystones by talking to the Keystone Vendor in Stormwind, Orgrimmar and Silvermoon. The nearby Dungeon Teleports NPC will assist you with transportation. This NPC will now also appear at the beginning of each dungeon on Mythic difficulty who can teleport players back to a capital city." },
            { type = "p", text = "Provided that the items equipped on your character are at least item level 226, they will scale automatically to a higher level as needed to support Dungeon testing." },
            { type = "h3", text = "Dungeon Update" },
            { type = "p", text = "Altar of Fangs We updated mechanics and pacing in the Rav’i and The Writhing Coil encounters to improve visual clarity and player engagement. We also made tuning adjustments to enemies that are more difficult or chaotic than intended, such as Ascendant Serpent, Ritual Chieftain, and Venom Leech." },
            { type = "list_item", text = "General", level = 0 },
            { type = "list_item", text = "Caustic Mist Totem", level = 1 },
            { type = "list_item", text = "Interaction range increased", level = 2 },
            { type = "list_item", text = "Taking damage no longer interrupts the Destroy cast", level = 2 },
            { type = "list_item", text = "Liadrin now casts Blessing of Protection on players jumping into The Carnage Pit to prevent fall damage", level = 1 },
            { type = "list_item", text = "Rav’i", level = 0 },
            { type = "list_item", text = "Improved the visual clarity of Fresh Meat", level = 1 },
            { type = "list_item", text = "Rav’i now gains Scent of Blood when she is closest to a pile with Fresh Meat, increasing her attack speed", level = 1 },
            { type = "list_item", text = "Carrion Burst damage increased by 50%", level = 1 },
            { type = "list_item", text = "Feeding Frenzy damage absorb increased by 100%", level = 1 },
            { type = "list_item", text = "Regurgitate’s damage has been reduced by 25% and wave size has been increased", level = 1 },
            { type = "list_item", text = "Triple Shot damage increased by 40%", level = 1 },
            { type = "list_item", text = "The Writhing Coil", level = 0 },
            { type = "list_item", text = "Now casts Toxic Atrophy, an interruptible spell that reduces the damage and movement speed of all players", level = 1 },
            { type = "list_item", text = "Synchronized Venom duration increased to 35 sec (was 15 sec)", level = 1 },
            { type = "list_item", text = "Uncoiled Writhes no longer apply Spiteful Venom", level = 1 },
            { type = "list_item", text = "Vine Grip", level = 1 },
            { type = "list_item", text = "Now requires all living players pulling to interrupt Death Rattle", level = 2 },
            { type = "list_item", text = "Now applied to all players automatically by Orweyna", level = 2 },
            { type = "list_item", text = "Extra action button removed", level = 2 },
            { type = "list_item", text = "Movement speed reduction reduced", level = 2 },
            { type = "list_item", text = "Zul’jan", level = 0 },
            { type = "list_item", text = "Axegrinder", level = 1 },
            { type = "list_item", text = "Cast time and channel duration increased", level = 2 },
            { type = "list_item", text = "Now displays red arrow visuals to indicate the direction of each throw", level = 2 },
            { type = "list_item", text = "Axes now move faster and inflict increased damage when they are first thrown", level = 2 },
            { type = "list_item", text = "Base damage increased by 25%", level = 2 },
            { type = "list_item", text = "Bloodletting damage reduced by 9%", level = 1 },
            { type = "list_item", text = "Boneslicer", level = 1 },
            { type = "list_item", text = "DoT duration reduced to 7 sec (was 9 sec)", level = 2 },
            { type = "list_item", text = "Damage increased by 12.5%", level = 2 },
            { type = "list_item", text = "Ritual of the Fang", level = 1 },
            { type = "list_item", text = "Channel duration reduced to 8 sec (was 10 sec)", level = 2 },
            { type = "list_item", text = "Added additional visuals to beams that are not being intercepted", level = 2 },
            { type = "list_item", text = "Fang Empowered damage increased by 100%", level = 2 },
            { type = "list_item", text = "Ritual Venom is now present on non-Mythic difficulties, but does not stack", level = 2 },
            { type = "list_item", text = "Ritual Venom damage reduced by 50% on non-Mythic difficulties", level = 2 },
            { type = "list_item", text = "Ascendant Serpent", level = 0 },
            { type = "list_item", text = "Health reduced by 12.5%", level = 1 },
            { type = "list_item", text = "All ability cooldowns increased", level = 1 },
            { type = "list_item", text = "Hatchlings created by Infest now die when the Ascendant Serpent is defeated", level = 1 },
            { type = "list_item", text = "Reduced the number of Virulent Twisters created by Virulent Whirl", level = 1 },
            { type = "list_item", text = "Blade of the Altar", level = 0 },
            { type = "list_item", text = "Laced Edge now targets tanks", level = 1 },
            { type = "list_item", text = "Hatchling", level = 0 },
            { type = "list_item", text = "Melee damage reduced by 50%", level = 1 },
            { type = "list_item", text = "High Evolutionist", level = 0 },
            { type = "list_item", text = "Envenom DoT damage reduced by 37.5%", level = 1 },
            { type = "list_item", text = "Primal Serpent", level = 0 },
            { type = "list_item", text = "Fetid Spit cooldown increased slightly", level = 1 },
            { type = "list_item", text = "Ravenous Descendant", level = 0 },
            { type = "list_item", text = "Base attack speed reduced by 33%", level = 1 },
            { type = "list_item", text = "Ritual Chieftain", level = 0 },
            { type = "list_item", text = "Blood Sacrifice no longer ignores armor", level = 1 },
            { type = "list_item", text = "Blood Sacrifice heal absorb reduced by 10%", level = 1 },
            { type = "list_item", text = "Venom Leech", level = 0 },
            { type = "list_item", text = "Reduced the number of pools created by Septic Spatter", level = 1 },
            { type = "list_item", text = "Septic Spatter duration reduced to 30 sec (was 1 min)", level = 1 },
            { type = "p", text = "Murder Row We’re reducing the number of Bribed Guards that players need to fight, as well as improving the pacing of the cantina event. For Xathuux the Annihilator’s encounter, we are increasing the duration of Burning Steps to further challenge the tank’s movement and positioning during the encounter." },
            { type = "list_item", text = "General", level = 0 },
            { type = "list_item", text = "Reduced number of Bribed Guards in the first area of the dungeon from 4 to 2, and reduced the enemy forces requirement", level = 1 },
            { type = "list_item", text = "Cantina Event", level = 0 },
            { type = "list_item", text = "Enchanted Broom’s movement speed reduction reduced from 50% to 20%", level = 1 },
            { type = "list_item", text = "Warehouse Worker", level = 0 },
            { type = "list_item", text = "Health reduced by 12.5% and no longer flees combat at 30% health", level = 1 },
            { type = "list_item", text = "Corrupted Warlock", level = 0 },
            { type = "list_item", text = "Addressed an issue where Curse of Doom was not splitting damage among all players hit", level = 1 },
            { type = "list_item", text = "Xathuux the Annihilator", level = 0 },
            { type = "list_item", text = "Demonic Rage’s damage reduced by 15%", level = 1 },
            { type = "list_item", text = "Burning Steps’ duration increased to 130 sec (was 65 sec)", level = 1 },
            { type = "p", text = "Den of Nalorakk We are making adjustments to the outgoing damage during Fury of the War God in the Nalorakk encounter. We are also changing creatures that are more challenging than intended, like Grizzled Warbringer and Bonded Beasttamer." },
            { type = "list_item", text = "Nalorakk", level = 0 },
            { type = "list_item", text = "Zul’Jarra now jumps behind the tank before casting Defensive Stance during Overwhelming Onslaught", level = 1 },
            { type = "list_item", text = "Improved visibility of the impact area of Forceful Slam", level = 1 },
            { type = "list_item", text = "Echo of Nalorakk no longer casts Spectral Slash on the intercepting player during Fury of the War God", level = 1 },
            { type = "list_item", text = "Echoing Fury’s damage reduced by 30%", level = 1 },
            { type = "list_item", text = "Grizzled Warbringer", level = 0 },
            { type = "list_item", text = "Addressed an issue where the rider can melee a random player instead of the threat target", level = 1 },
            { type = "list_item", text = "Primal Echo’s damage over time duration reduced to 3 sec (was 8 sec) and periodic damage increased by 50%", level = 1 },
            { type = "list_item", text = "Bonded Beasttamer", level = 0 },
            { type = "list_item", text = "Overwhelmed Prey has been removed", level = 1 },
            { type = "list_item", text = "Territorial Matriarch", level = 0 },
            { type = "list_item", text = "Mother’s Wrath now removes all stacks when dispelled", level = 1 },
            { type = "p", text = "Voidscar Arena We are updating pacing and mechanics for Taz’Rah and Charonus to make the encounters more engaging. To provide more unique challenges, Raj’kess the Spellstorm and Agitated Voidscythe have received updates to their ability packages. Devouring Brutalizer’s Devour cast time has also been increased to allow more time for players to kill the target creature." },
            { type = "list_item", text = "Taz’Rah", level = 0 },
            { type = "list_item", text = "Dark Bloom’s movement speed has been reduced", level = 1 },
            { type = "list_item", text = "Void Fissure’s duration increased to 120 sec (was 80 sec)", level = 1 },
            { type = "list_item", text = "Time between Dark Bloom and Nether Dash has been reduced", level = 1 },
            { type = "list_item", text = "Atroxus", level = 0 },
            { type = "list_item", text = "Hulking Claw’s periodic damage reduced by 21%", level = 1 },
            { type = "list_item", text = "Poison Splash’s periodic damage has been reduced by 10% and now creates less Poison Pools", level = 1 },
            { type = "list_item", text = "Charonus", level = 0 },
            { type = "list_item", text = "Dark Waves is a new spell added to the encounter that targets the tank after Gravitic Orbs", level = 1 },
            { type = "list_item", text = "Atomized’s duration increased to 15 sec (was 10 sec)", level = 1 },
            { type = "list_item", text = "Raj’kess the Spellstorm", level = 0 },
            { type = "list_item", text = "Thundering Storm now also targets random players with lightning strikes", level = 1 },
            { type = "list_item", text = "Now creates Orbs of Disruptions that reduce Haste of all players if not promptly killed", level = 1 },
            { type = "list_item", text = "Raging Typhoon has been removed", level = 1 },
            { type = "list_item", text = "Agitated Voidscythe", level = 0 },
            { type = "list_item", text = "Corrosive Essence now prefers players without the debuff", level = 1 },
            { type = "list_item", text = "Rip and Slice has been changed from a channeled frontal attack to a tank attack", level = 1 },
            { type = "p", text = "The Blinding Vale We are making spawning adjustments to the left side of the dungeon to make it more approachable for players." },
            { type = "list_item", text = "General", level = 0 },
            { type = "list_item", text = "Spawning on the left path has been adjusted", level = 1 },
            { type = "list_item", text = "First Sporeblight Belcher has been moved back and no longer patrols", level = 2 },
            { type = "list_item", text = "Replaced the Virid Grovekeeper that channels on a Sporeblight Belcher with Radiant Spellsower", level = 2 },
            { type = "list_item", text = "Virid Grovekeeper", level = 0 },
            { type = "list_item", text = "Uproot’s damage has been reduced by 20%", level = 1 },
            { type = "p", text = "Ruby Life Pools For Ruby Life Pools, we reduced incoming damage from the creatures prior to Melidrussa Chillworn to reduce the intensity of certain ability overlaps. Dungeon-wide, we adjusted some creature pathing to make movement patterns more predictable. Certain creatures have also seen health increases and damage adjustments to reward priority targeting." },
            { type = "list_item", text = "General", level = 0 },
            { type = "list_item", text = "Reduced timer to 29 minutes from 30 minutes", level = 1 },
            { type = "list_item", text = "Melidrussa Chillworn", level = 0 },
            { type = "list_item", text = "Frigid Shard", level = 1 },
            { type = "list_item", text = "Fixed an issue where this ability was doing less damage than intended", level = 2 },
            { type = "list_item", text = "Kokia Blazehoof", level = 0 },
            { type = "list_item", text = "Searing Blows", level = 1 },
            { type = "list_item", text = "Can now be dodged and parried", level = 2 },
            { type = "list_item", text = "Reduced periodic damage by 25%", level = 2 },
            { type = "list_item", text = "Primal Juggernaut", level = 0 },
            { type = "list_item", text = "Adjusted the timing of the second Primal Juggernaut’s pathing to make the creature’s movement more predictable", level = 1 },
            { type = "list_item", text = "Excavating Blast", level = 1 },
            { type = "list_item", text = "Reduced impact damage by 8%", level = 2 },
            { type = "list_item", text = "Deepstone Earthshaper", level = 0 },
            { type = "list_item", text = "Tectonic Strike", level = 1 },
            { type = "list_item", text = "Reduced damage vulnerability per stack to 30% from 35%", level = 2 },
            { type = "list_item", text = "Earthbound Guardian", level = 0 },
            { type = "list_item", text = "Earthbound’s Imprint", level = 1 },
            { type = "list_item", text = "Reduced periodic damage by 12.5%", level = 2 },
            { type = "list_item", text = "Defier Draghar", level = 0 },
            { type = "list_item", text = "Increased health by 25%", level = 1 },
            { type = "list_item", text = "Blazebound Destroyer", level = 0 },
            { type = "list_item", text = "Inferno", level = 1 },
            { type = "list_item", text = "Reduced impact damage by 9%", level = 2 },
            { type = "list_item", text = "Increased health by 22%", level = 1 },
            { type = "list_item", text = "Flamegullet", level = 0 },
            { type = "list_item", text = "Molten Blood", level = 1 },
            { type = "list_item", text = "Adjusted pathing to make the creature’s movement more predictable", level = 2 },
            { type = "list_item", text = "Reduced damage increase per stack to 15% from 25%", level = 2 },
