            { type = "list_item", text = "No longer a Poison dispel", level = 2 },
            { type = "list_item", text = "Venomous Strike", level = 1 },
            { type = "list_item", text = "No longer a Poison dispel", level = 2 },
            { type = "list_item", text = "The slow fields on the way to the gauntlet now display a screen effect", level = 0 },
            { type = "list_item", text = "Also removed this field from the cosmetic pillar on the way to boss 3", level = 1 },
            { type = "list_item", text = "Added a short delay for when Loose Sparks can harm a player after forming", level = 0 },
            { type = "p", text = "Kings’ Rest For boss encounters, we are adjusting mechanics on The Golden Serpent and Mchimba to make them more engaging. We are also reducing the pacing of Dazar, The First King’s encounter to create more room between abilities. For normal enemy creatures, we are further increasing the cooldown of Healing Tide Totem and reducing its healing frequency." },
            { type = "list_item", text = "General", level = 0 },
            { type = "list_item", text = "Enemies after Mchimba now spawn faster as players approach the area", level = 1 },
            { type = "list_item", text = "The Golden Serpent", level = 0 },
            { type = "list_item", text = "Serpentine Gust has been reworked to a channel spell that inflicts Nature damage every 1 sec for 5 sec and pushes players back", level = 1 },
            { type = "list_item", text = "Mchimba", level = 0 },
            { type = "list_item", text = "Health reduced by 10%", level = 1 },
            { type = "list_item", text = "Burn Corruption now applies a rim visual on the targeted player before the effect resolves, its damage has been reduced by 62.5%", level = 1 },
            { type = "list_item", text = "Burning Ground now grows into full size after 5 sec", level = 1 },
            { type = "list_item", text = "Drain Fluids now periodically creates Explosive Acids in nearby area, inflicting Nature damage to players hit", level = 1 },
            { type = "list_item", text = "Mchimba now casts Awakening Slam, inflicting Shadow damage to all players and causing Half-Finished Mummies to fall out from coffins", level = 1 },
            { type = "list_item", text = "Dazar, The First King", level = 0 },
