            { type = "list_item", text = "Royal Berserker", level = 0 },
            { type = "list_item", text = "Bloodthirsty Axe now prefers players without the debuff", level = 1 },
            { type = "list_item", text = "Spectral Shaman", level = 0 },
            { type = "list_item", text = "Healing Tide Totem cooldown increased by 28% and now heals every 2.5 sec (was 2 sec)", level = 1 },
